def _structured_theory_packet_fixture(
    packet_id: str = "theory_derivation:structured",
) -> dict[str, object]:
    return {
        "artifact_kind": "TheoryDerivationPacket",
        "packet_id": packet_id,
        "theorem_cards": [
            {
                "theorem_id": "T_FINITE_SAMPLE_GATE_FIXTURE",
                "conclusion": (
                    "The preregistered candidate error bounds are 1e-12 and 0.1."
                ),
            }
        ],
        "theory_derivation_packet": {
            "derivation_summary": "identify estimand, build score, bound remainder",
            "derivation_steps": [
                {"id": "identify", "claim": "identify estimand"},
                {"id": "score", "claim": "build orthogonal score"},
                {"id": "remainder", "claim": "bound remainder"},
            ],
            "equation_chain": [
                {"step_id": "estimand", "lhs": "psi", "rhs": "E[m1-m0]"},
                {
                    "step_id": "expansion",
                    "lhs": "sqrt(n)(psi_hat-psi)",
                    "rhs": "sqrt(n)P_n phi + o_p(1)",
                },
            ],
            "assumption_ledger": [
                {"assumption": "exchangeability", "used_in": ["identify"]},
                {"assumption": "positivity", "used_in": ["score"]},
            ],
            "formalization_handoff": {
                "source_theorem_target": "aipw_asymptotic_normality",
                "semantic_alignment_constraints": ["keep nuisance remainder"],
            },
        },
        "theory_derivation_contract": {
            "min_derivation_steps": 3,
            "n_derivation_steps": 3,
            "n_equation_chain_steps": 2,
            "n_assumption_ledger_rows": 2,
            "has_formalization_handoff": True,
        },
    }


def _theory_informed_metric_context_fixture() -> dict[str, object]:
    theory_packet = _structured_theory_packet_fixture()
    theory_packet_id = str(theory_packet["packet_id"])
    return {
        "theory_packet_id": theory_packet_id,
        "architect_metric_protocol_theory_material": (
            build_theory_informed_metric_protocol_material(
                theory_packet=theory_packet,
                theory_packet_id=theory_packet_id,
            )
        ),
        "architect_metric_protocol_gate": {
            "artifact_kind": "RuntimeArchitectMetricProtocolGate",
            "source_theory_packet_id": theory_packet_id,
            "required_disposition": "PREEXECUTION_REVIEW_ACCEPTED",
            "execution_authorized": False,
        },
    }


def _with_accepted_metric_protocol(
    architect_context: dict[str, object],
    *,
    required_runtime_replicates: int,
    threshold: float = 0.9,
) -> dict[str, object]:
    context = json.loads(json.dumps(architect_context))
    theory_material = context.get(
        "architect_metric_protocol_theory_material", {}
    )
    theory_material = (
        dict(theory_material) if isinstance(theory_material, dict) else {}
    )
    source_theory_packet_id = str(
        theory_material.get("source_theory_packet_id", "") or ""
    )
    source_theory_packet_hash = str(
        theory_material.get("source_theory_packet_hash", "") or ""
    )
    response = _architect_sample_response(
        required_runtime_replicates=required_runtime_replicates
    )
    contract = response["evidence_contract"]
    requirements = contract["empirical_metric_requirements"]
    requirements[0]["threshold"] = threshold
    requirement_set_id = runtime_module.generated_metric_requirement_set_id(
        requirements
    )
    context["architect_metric_requirement_authoring"] = {
        "artifact_kind": "ArchitectMetricRequirementAuthoringPacket",
        "packet_id": "architect_metric_requirement_authoring:test-accepted",
        "source_theory_packet_id": source_theory_packet_id,
        "source_theory_packet_hash": source_theory_packet_hash,
        "empirical_metric_requirements": requirements,
        "empirical_metric_requirement_set_id": requirement_set_id,
        "semantic_review_status": "ACCEPT",
        "semantic_review_packet_id": (
            "architect_metric_semantic_review:test-accepted"
        ),
        "semantic_review_packet_hash": "test-review-hash",
        "semantic_review_model": "independent-test-reviewer",
        "semantic_review_model_tier": "sonnet",
        "semantic_review_independent_agent": True,
        "semantic_review_independent_invocation": True,
        "semantic_review_independent_model": True,
        "semantic_review_independent_model_tier": False,
        "proof_evidence_status": (
            "ARCHITECT_METRIC_REQUIREMENT_AUTHORING_NOT_PROOF_EVIDENCE"
        ),
    }
    runtime_plan = context.get("architect_runtime_plan", {})
    runtime_plan = dict(runtime_plan) if isinstance(runtime_plan, dict) else {}
    contract = dict(contract)
    contract["capability_eval_requires_typed_metric_contracts"] = True
    contract["empirical_metric_requirements"] = requirements
    contract["empirical_metric_requirement_set_id"] = requirement_set_id
    contract["empirical_metric_protocol_phase"] = (
        runtime_module.METRIC_PROTOCOL_PHASE_PREEXECUTION_REVIEW_ACCEPTED
    )
    contract["metric_protocol_execution_authorized"] = True
    contract["empirical_metric_requirements_preexecution_review"] = {
        "artifact_kind": "ArchitectMetricPreExecutionReviewCertificate",
        "overall_verdict": "ACCEPT",
        "review_packet_id": "architect_metric_semantic_review:test-accepted",
        "review_packet_hash": "test-review-hash",
        "reviewed_empirical_metric_requirement_set_id": requirement_set_id,
        "source_theory_packet_id": source_theory_packet_id,
        "source_theory_packet_hash": source_theory_packet_hash,
        "reviewer_model": "independent-test-reviewer",
        "reviewer_model_tier": "sonnet",
        "independent_agent": True,
        "independent_invocation": True,
        "pre_execution_review": True,
        "execution_results_observed": False,
    }
    runtime_plan["evidence_contract"] = contract
    context["architect_runtime_plan"] = runtime_plan
    context["architect_metric_protocol_gate"] = {
        "artifact_kind": "RuntimeArchitectMetricProtocolGate",
        "source_theory_packet_id": str(context.get("theory_packet_id", "") or ""),
        "source_theory_packet_hash": source_theory_packet_hash,
        "required_disposition": "PREEXECUTION_REVIEW_ACCEPTED",
        "execution_authorized": True,
        "consumed": True,
        "accepted_requirement_set_id": requirement_set_id,
    }
    return context


def _typed_metric_contract_fixture(
    artifact_id: str,
    *,
    metric_path: list[str | int] | None = None,
    required_runtime_replicates: int | None = None,
) -> dict[str, object]:
    row: dict[str, object] = {
        "contract_id": f"metric-contract:{artifact_id}",
        "requirement_id": "architect:empirical-coverage",
        "artifact_id": artifact_id,
        "metric_path": metric_path or ["empirical_coverage"],
        "metric_semantics": "empirical coverage across bounded runtime replicates",
        "measurement_protocol": (
            "return the fraction of runtime replicates satisfying the declared "
            "coverage event"
        ),
        "operator": ">=",
        "threshold": 0.9,
        "tolerance": 0.0,
        "aggregation": "identity",
        "required": True,
        "source_anchors": ["architect:capability-eval"],
    }
    if required_runtime_replicates is not None:
        row["required_runtime_replicates"] = required_runtime_replicates
    return row


def _typed_metric_requirement_fixture(
    *target_subsystems: str,
    threshold: float = 0.9,
    required_runtime_replicates: int = 12,
) -> dict[str, object]:
    return {
        "requirement_id": "architect:empirical-coverage",
        "target_subsystems": list(target_subsystems),
        "metric_semantics": "empirical coverage across bounded runtime replicates",
        "measurement_protocol": (
            "return the fraction of runtime replicates satisfying the declared "
            "coverage event"
        ),
        "required_runtime_replicates": required_runtime_replicates,
        "operator": ">=",
        "threshold": threshold,
        "tolerance": 0.0,
        "aggregation": "identity",
        "required": True,
        "source_anchors": ["architect:capability-eval"],
    }


