def test_runtime_requested_evidence_contract_reaches_subsystems() -> None:
    contract = _runtime_requested_evidence_contract(
        formal_verification_policy="advisory",
        recommended_research_path="simulation_first",
    )
    context = _runtime_architect_context_with_requested_evidence_contract(
        {},
        formal_verification_policy="advisory",
        recommended_research_path="simulation_first",
    )
    control = _architect_control_payload(context, "SimulationEvaluator")

    assert contract["formal_verification_policy"] == "advisory"
    assert contract["recommended_research_path"] == "simulation_first"
    assert contract["formal_required_for_final"] is False
    assert "formal_targets" not in contract
    assert "simulation_targets" not in contract
    assert contract["formal_target_authoring_required"] is False
    assert "formal gaps must remain explicit" in contract[
        "formal_target_completion_policy"
    ]
    assert contract["simulation_target_authoring_required"] is True
    assert control["formal_verification_policy"] == "advisory"
    assert control["recommended_research_path"] == "simulation_first"
    assert control["formal_required_for_final"] is False
    assert control["evidence_contract"]["recommended_research_path"] == (
        "simulation_first"
    )

    merged_context = _runtime_architect_context_with_requested_evidence_contract(
        {
            "runtime_requested_evidence_contract": {
                "existing_context_flag": "keep",
                "capability_eval_requires_generated_code_semantic_review": False,
            }
        },
        formal_verification_policy="advisory",
        recommended_research_path="simulation_first",
        evaluation_mode="capability_eval",
        algorithm_engineer_generated_code_repair_yield_after_attempts=1,
        simulation_evaluator_generated_code_repair_yield_after_attempts=1,
        formalizer_lean_candidate_repair_yield_to_gap_planner_after_attempts=1,
    )
    merged_contract = merged_context["runtime_requested_evidence_contract"]
    assert merged_contract["existing_context_flag"] == "keep"
    assert (
        merged_contract["capability_eval_requires_generated_code_semantic_review"]
        is True
    )
    assert (
        merged_contract[
            "capability_eval_algorithm_engineer_generated_code_repair_yield_after_attempts"
        ]
        == 1
    )
    assert (
        merged_contract[
            "capability_eval_simulation_evaluator_generated_code_repair_yield_after_attempts"
        ]
        == 1
    )
    assert (
        merged_contract[
            "capability_eval_formalizer_lean_candidate_repair_yield_to_gap_planner_after_attempts"
        ]
        == 1
    )


def test_research_path_execution_summary_detects_control_propagation() -> None:
    results = [
        {
            "blackboard": {
                "artifacts": {
                    "retrieval:test": {
                        "artifact_kind": "RuntimeRetrievalMemoryManifest",
                        "runtime_architect_control": {
                            "subsystem": "RetrievalMemory",
                            "formal_verification_policy": "required",
                            "recommended_research_path": "proof_first",
                            "formal_required_for_final": True,
                            "evidence_contract": {
                                "formal_verification_policy": "required",
                                "recommended_research_path": "proof_first",
                                "formal_required_for_final": True,
                            },
                        },
                    },
                    "simulation:test": {
                        "artifact_kind": "RuntimeSimulationManifest",
                        "runtime_architect_control": {
                            "subsystem": "SimulationEvaluator",
                            "formal_verification_policy": "required",
                            "recommended_research_path": "proof_first",
                            "formal_required_for_final": True,
                            "evidence_contract": {
                                "formal_verification_policy": "required",
                                "recommended_research_path": "proof_first",
                                "formal_required_for_final": True,
                            },
                        },
                    },
                }
            }
        }
    ]

    summary = _runtime_research_path_execution_summary(
        results,
        effective_formal_verification_policy="required",
        effective_recommended_research_path="proof_first",
    )

    assert summary["path_control_propagated"] is True
    assert summary["n_current_artifacts"] == 2
    assert summary["n_current_artifacts_missing_architect_control"] == 0
    assert summary["n_produced_artifact_ids_missing_from_blackboard"] == 0
    assert summary["n_controlled_artifacts"] == 2
    assert summary["n_policy_mismatches"] == 0
    assert summary["n_path_mismatches"] == 0
    assert summary["by_subsystem"]["RetrievalMemory"][
        "recommended_research_paths"
    ] == ["proof_first"]
    assert summary["by_subsystem"]["SimulationEvaluator"][
        "formal_verification_policies"
    ] == ["required"]

    mismatch_summary = _runtime_research_path_execution_summary(
        results,
        effective_formal_verification_policy="advisory",
        effective_recommended_research_path="simulation_first",
    )

    assert mismatch_summary["path_control_propagated"] is False
    assert mismatch_summary["n_policy_mismatches"] == 2
    assert mismatch_summary["n_path_mismatches"] == 2


