def test_runtime_failure_summary_does_not_label_budget_pending_as_failure() -> None:
    completion = _runtime_completion_summary(
        [
            {
                "status": "MAX_ITERATIONS_REACHED",
                "final_task_id": "theory-critic-revise:q1:abc",
                "traces": [
                    {
                        "task": {
                            "task_id": "critic:q1:abc",
                            "inputs": {
                                "question": {"id": "q1", "title": "Question 1"},
                            },
                        },
                        "subsystem": "CriticEvaluator",
                        "status": "REVISE",
                        "failure_classification": "critic_requested_theory_revision",
                        "next_task_id": "theory-critic-revise:q1:abc",
                        "next_task": {
                            "task_id": "theory-critic-revise:q1:abc",
                            "owner_subsystem": "TheoryDeveloper",
                            "objective": "Revise the theory packet from critic feedback.",
                            "inputs": {
                                "question": {"id": "q1", "title": "Question 1"},
                                "environment_feedback": {
                                    "failure_classification": (
                                        "critic_requested_theory_revision"
                                    ),
                                    "required_repair": "address formal gap",
                                },
                            },
                            "allowed_tools": ["model_backend", "rag_memory"],
                            "budget": {},
                            "expected_artifacts": [
                                "critic_revised_theory_derivation_packet"
                            ],
                            "acceptance_gate": "revised packet addresses critic feedback",
                            "stop_condition": "reroute through gates",
                        },
                    }
                ],
            }
        ]
    )
    summary = _runtime_failure_summary(completion)

    assert summary["has_failure"] is False
    assert summary["has_incomplete_pending_work"] is True
    assert summary["failed_subsystem"] == ""
    assert summary["terminal_subsystem"] == "CriticEvaluator"
    assert summary["terminal_kind"] == "budget_exhausted_with_pending_next_task"
    assert summary["pending_next_task_id"] == "theory-critic-revise:q1:abc"
    assert summary["pending_next_task"]["owner_subsystem"] == "TheoryDeveloper"
    assert (
        summary["pending_next_task"]["inputs"]["environment_feedback"][
            "required_repair"
        ]
        == "address formal gap"
    )


def test_runtime_pending_next_task_rows_preserve_every_question() -> None:
    results: list[dict[str, Any]] = [
        {
            "status": "FAILED",
            "final_task_id": "algorithm:q0",
            "traces": [
                {
                    "task_id": "algorithm:q0",
                    "task": {
                        "task_id": "algorithm:q0",
                        "inputs": {
                            "question": {"id": "q0", "title": "Failed"}
                        },
                    },
                    "subsystem": "AlgorithmEngineer",
                    "status": "FAILED",
                    "failure_classification": "subsystem_exception",
                    "next_task_id": "",
                }
            ],
        }
    ]
    for question_id, owner in (
        ("q1", "FormalTargetSemanticReviewer"),
        ("q2", "FormalizationEvaluator"),
    ):
        pending_task_id = f"continue:{question_id}"
        results.append(
            {
                "status": "MAX_ITERATIONS_REACHED",
                "final_task_id": pending_task_id,
                "traces": [
                    {
                        "task_id": f"last:{question_id}",
                        "task": {
                            "task_id": f"last:{question_id}",
                            "inputs": {
                                "question": {
                                    "id": question_id,
                                    "title": f"Question {question_id}",
                                }
                            },
                        },
                        "subsystem": "FormalizationEvaluator",
                        "status": "REVISE",
                        "failure_classification": "bounded_continuation",
                        "next_task_id": pending_task_id,
                        "next_task": {
                            "task_id": pending_task_id,
                            "owner_subsystem": owner,
                            "objective": "continue bounded work",
                            "inputs": {
                                "question": {
                                    "id": question_id,
                                    "title": f"Question {question_id}",
                                }
                            },
                        },
                    }
                ],
            }
        )

    completion = _runtime_completion_summary(results)
    pending_rows = _runtime_pending_next_task_rows(completion)
    failure_summary = _runtime_failure_summary(completion)

    assert [row["question_id"] for row in pending_rows] == ["q1", "q2"]
    assert [row["pending_next_task_id"] for row in pending_rows] == [
        "continue:q1",
        "continue:q2",
    ]
    assert pending_rows[0]["pending_next_task"]["owner_subsystem"] == (
        "FormalTargetSemanticReviewer"
    )
    assert pending_rows[1]["pending_next_task"]["owner_subsystem"] == (
        "FormalizationEvaluator"
    )
    assert all(
        row["proof_evidence_status"]
        == "PENDING_RUNTIME_TASK_NOT_PROOF_EVIDENCE"
        for row in pending_rows
    )
    assert failure_summary["terminal_question_id"] == "q0"
    assert failure_summary["pending_question_id"] == "q1"
    assert failure_summary["n_pending_next_tasks"] == 2
    assert failure_summary["pending_next_task_id"] == "continue:q1"
    scoped_rows = runtime_module._runtime_rows_scoped_to_question(
        [
            {"question_id": "q1", "learning_task": "q1_only"},
            {
                "learning_task": "q2_only",
                "input_summary": {"question_id": "q2"},
            },
            {"learning_task": "shared_policy"},
        ],
        "q1",
    )
    assert [row["learning_task"] for row in scoped_rows] == [
        "q1_only",
        "shared_policy",
    ]


