    correct_module = (
        lean_project
        / ".lake"
        / "packages"
        / "mathlib"
        / "Mathlib"
        / "MeasureTheory"
        / "Measure"
        / "ProbabilityMeasure.lean"
    )
    correct_module.parent.mkdir(parents=True, exist_ok=True)
    correct_module.write_text("import Mathlib\n", encoding="utf-8")
    task = AgentTask(
        task_id="task:formalizer_candidate_bad_import",
        owner_subsystem="FormalizationEvaluator",
        objective="materialize guessed unavailable Lean import for diagnostics",
    )

    manifest = _materialize_formalizer_lean_candidate_artifacts(
        root=tmp_path / "formalizer_lean_candidates",
        question=question,
        task=task,
        proposal_packet={
            "packet_id": "formalizer_proposal:bad_import",
            "formal_targets": [
                {
                    "id": "bad_import_candidate",
                    "candidate_lean_declaration": "bad_import_candidate",
                    "informal_source": "candidate imports a guessed Mathlib path",
                    "lean_statement_sketch": (
                        "import Mathlib.Probability.ProbabilityMeasure\n\n"
                        "theorem bad_import_candidate (p : Prop) (hp : p) : p := by\n"
                        "  exact hp\n"
                    ),
                    "expected_status": "NEEDS_KERNEL_CHECK",
                }
            ],
        },
        local_lean=True,
        lean_project=lean_project,
        lean_timeout=10,
    )

    row = manifest["candidate_rows"][0]
    assert manifest["n_candidate_sources"] == 1
    assert manifest["n_candidate_artifacts_written"] == 1
    assert manifest["n_precheck_rejected"] == 0
    assert row["precheck_status"] == (
        "MATERIALIZED_WITH_PRECHECK_DIAGNOSTICS_REQUIRES_LOCAL_LEAN_OR_AXLE"
    )
    assert row["blocking_precheck_errors"] == []
    assert row["artifact_path"]
    assert row["local_lean_attempted"] is True
    assert "imports unavailable module" in " ".join(row["precheck_errors"])
    assert "Mathlib.Probability.ProbabilityMeasure" in " ".join(
        row["precheck_errors"]
    )
    assert "Mathlib.MeasureTheory.Measure.ProbabilityMeasure" in " ".join(
        row["precheck_errors"]
    )


