def test_formalizer_prompt_repair_instructions_preserve_source_theorem_after_target_drift() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet=_runtime_sample_response(),
        simulation_manifest={"manifest_id": "simulation_manifest:test"},
        algorithm_manifest={"manifest_id": "algorithm_sandbox_manifest:test"},
        registered_problem={"question_id": question.id, "problem_class": "conformal"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary={},
        environment_feedback={
            "feedback_type": "formalizer_lean_candidate_local_lean_feedback",
            "failure_classification": (
                "formalizer_lean_candidate_precheck_rejected"
            ),
            "candidate_diagnostics": [
                {
                    "candidate_id": "split_conformal_finite_sample_coverage",
                    "candidate_kind": "formal_target_lean_statement_sketch",
                    "source_field": "formal_targets",
                    "precheck_status": "REJECTED_BY_RUNTIME_PRECHECK",
                    "precheck_errors": [
                        (
                            "source-theorem target drift: semantic constraints "
                            "narrow or replace the stated source theorem instead "
                            "of preserving it"
                        )
                    ],
                    "local_lean_attempted": False,
                    "local_lean_compiled": False,
                }
            ],
            "target_shape_contract": {
                "contract_kind": "source_theorem_target_preservation",
                "required_conclusion_family": (
                    "probability_or_measure_coverage_claim"
                ),
                "required_conclusion_shape": (
                    "The Lean target must conclude an explicit probability or "
                    "measure lower bound tied to the coverage event."
                ),
            },
            "candidate_reroute_options": [
                (
                    "Arithmetic helper lemmas must be routed separately and not "
                    "claimed as the source theorem."
                )
            ],
        },
    )

    assert "Mandatory source-theorem target-preservation repair" in prompt
    assert "Mandatory target-drift two-lane repair" in prompt
    assert "source_theorem_lane" in prompt
    assert "support_lemma_lane" in prompt
    assert "Target-shape contract is mandatory" in prompt
    assert "probability_or_measure_coverage_claim" in prompt
    assert "task-bound objects, assumptions, quantifiers, conclusion" in prompt
    assert "Do not replace it with a standalone arithmetic" in prompt
    assert "FORMAL_GAP" in prompt


