        simulation_manifest={"manifest_id": "simulation_manifest:test"},
        algorithm_manifest={"manifest_id": "algorithm_sandbox_manifest:test"},
        registered_problem={"question_id": question.id, "problem_class": "conformal"},
        theorem_goals=[],
