def test_algorithm_sandbox_failure_memory_replays_to_algorithm_prompt(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    algorithm_manifest = {
        "schema_version": 1,
        "artifact_kind": "RuntimeAlgorithmSandboxManifest",
        "manifest_id": "algorithm_sandbox_manifest:bad_generated_code",
        "created_at": "2026-06-24T12:00:00+00:00",
        "question": {"id": question.id, "title": question.title},
        "prototypes": [
            {
                "estimator_id": "custom_conformal",
                "prototype_status": "FAILED_METRIC_GATE",
                "executor": "generated_python_sandbox",
                "smoke_passed": False,
                "execution_smoke_passed": True,
                "metric_gate_errors": [
                    "empirical_coverage is degenerate zero coverage"
                ],
                "safety_errors": [],
                "script_path": "runs/generated_algorithm/bad.py",
                "code_excerpt": (
                    "def run_sandbox(seed:int, replicates:int)->dict:\n"
                    "    return {'empirical_coverage': 0.0}"
                ),
                "stderr_summary": "metric gate failed after local execution",
            }
        ],
        "n_prototypes": 1,
        "n_executed": 1,
        "n_passed": 0,
        "n_metric_gate_failed": 1,
        "n_generated_code_executed": 1,
        "n_unsafe_generated_code_rejected": 0,
        "boundary": "algorithm sandbox evidence is not theorem proof",
    }
    rows = _runtime_learning_rows(
        [{"blackboard": {"artifacts": {"algorithm": algorithm_manifest}}}]
    )
    assert len(rows) == 1
    assert rows[0]["learning_task"] == "algorithm_sandbox_execution_feedback"
    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(json.dumps(rows[0]) + "\n", encoding="utf-8")

    memory = _load_runtime_learning_memory([learning_path])
    feedback = _runtime_algorithm_sandbox_feedback_from_learning_memory(
        {"runtime_learning_memory": memory},
        question.id,
    )

    assert feedback["feedback_type"] == "algorithm_sandbox_execution_feedback"
    assert feedback["failure_classification"] == (
        "generated_algorithm_sandbox_metric_gate_failed"
    )
    assert feedback["prototypes"][0]["code_excerpt"].startswith("def run_sandbox")
    assert "metric gate failed" in feedback["prototypes"][0]["stderr_summary"]

    prompt = build_algorithm_engineer_prompt(
        question=question,
        theory_packet={
            "packet_id": "theory:test",
            "problem_card": {"estimand": "coverage"},
            "estimator_specs": [
                {"id": "custom_conformal", "name": "custom conformal estimator"}
            ],
            "theorem_cards": [],
            "simulation_ademp_spec": {},
        },
        simulation_manifest={
            "manifest_id": "simulation:test",
            "simulation_passed": True,
            "registered_procedures": [],
            "simulations": [],
            "implementation_gaps": [],
        },
        implementation_gaps=[
            {
                "estimator_id": "custom_conformal",
                "status": "REQUIRES_ALGORITHM_ENGINEER_ADAPTER",
            }
        ],
        environment_feedback=feedback,
    )

    assert "generated_algorithm_sandbox_metric_gate_failed" in prompt
    assert "empirical_coverage is degenerate zero coverage" in prompt
    assert "def run_sandbox" in prompt
    assert "metric gate failed after local execution" in prompt
    assert "Set metric_contracts to an empty array" in prompt
    assert "downstream SimulationEngineer owns DGP-based statistical evaluation" in prompt
    assert "Keep every contract_id" not in prompt


