def test_algorithm_runtime_injects_sandbox_failure_memory_without_current_feedback(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    algorithm_manifest = {
        "schema_version": 1,
        "artifact_kind": "RuntimeAlgorithmSandboxManifest",
        "manifest_id": "algorithm_sandbox_manifest:memory_metric_failure",
        "created_at": "2026-06-24T12:00:00+00:00",
        "question": {"id": question.id, "title": question.title},
        "prototypes": [
            {
                "estimator_id": "custom_conformal",
                "prototype_status": "FAILED_METRIC_GATE",
                "executor": "generated_python_sandbox",
                "smoke_passed": False,
                "execution_smoke_passed": True,
                "metric_gate_errors": ["coverage metric stayed at zero"],
                "code_excerpt": (
                    "def run_sandbox(seed:int, replicates:int)->dict:\n"
                    "    return {'empirical_coverage': 0.0}"
                ),
                "stderr_summary": "coverage metric gate failed",
            }
        ],
        "n_prototypes": 1,
        "n_executed": 1,
        "n_passed": 0,
        "n_metric_gate_failed": 1,
        "n_generated_code_executed": 1,
        "n_unsafe_generated_code_rejected": 0,
        "boundary": "algorithm sandbox evidence is not theorem proof",
    }
    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(
        json.dumps(
            _runtime_learning_rows(
                [{"blackboard": {"artifacts": {"algorithm": algorithm_manifest}}}]
            )[0]
        )
        + "\n",
        encoding="utf-8",
    )
    memory = _load_runtime_learning_memory([learning_path])

    class CapturingAlgorithmEngineer:
        def __init__(self) -> None:
            self.seen_feedback: dict[str, object] | None = None

        def propose(self, **kwargs: object) -> dict[str, object]:
            self.seen_feedback = dict(kwargs.get("environment_feedback", {}))
            return {
                "packet_id": "algorithm_engineer_proposal:memory_repair",
                "implementation_targets": [
                    {
                        "estimator_id": "custom_conformal",
                        "registered_template_hint": "none",
                    }
                ],
                "sandbox_code_drafts": [],
            }

    agent = CapturingAlgorithmEngineer()
    subsystem = AlgorithmEngineerRuntimeSubsystem(
        out_dir=tmp_path,
        n_runs=12,
        seed=20260624,
        proposal_agent=agent,  # type: ignore[arg-type]
        timeout_s=10,
    )
    blackboard = BlackboardState(
        project_id=f"runtime:{question.id}",
        artifacts={
            "theory:memory": {
                "packet_id": "theory:memory",
                "estimator_specs": [
                    {"id": "custom_conformal", "name": "Custom conformal"}
                ],
            },
            "simulation:memory": {
                "manifest_id": "simulation:memory",
                "simulation_passed": True,
            },
        },
    )
    task = AgentTask(
        task_id="algorithm:memory_repair",
        owner_subsystem="AlgorithmEngineer",
        objective="Use runtime memory sandbox diagnostics.",
        inputs={
            "question": {
                "id": question.id,
                "title": question.title,
                "description": question.description,
                "tags": list(question.tags),
            },
            "theory_packet_id": "theory:memory",
            "simulation_manifest_id": "simulation:memory",
            "implementation_gaps": [
                {
                    "estimator_id": "custom_conformal",
                    "status": "REQUIRES_ALGORITHM_ENGINEER_ADAPTER",
                }
            ],
            "architect_context": {"runtime_learning_memory": memory},
        },
    )

    result = subsystem.run(task, blackboard)

    assert result.status == "REVISE"
    assert agent.seen_feedback is not None
    assert agent.seen_feedback["feedback_type"] == (
        "algorithm_sandbox_execution_feedback"
    )
    assert agent.seen_feedback["failure_classification"] == (
        "generated_algorithm_sandbox_metric_gate_failed"
    )
    prototype = agent.seen_feedback["prototypes"][0]  # type: ignore[index]
    assert "def run_sandbox" in prototype["code_excerpt"]
    assert "coverage metric gate failed" in prototype["stderr_summary"]
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "AlgorithmEngineer"


