def test_simulation_evaluator_revises_after_nonexecutable_generated_simulation_code(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    theory_packet_id = "theory:simulation-custom"
    blackboard = BlackboardState(
        project_id=f"runtime:{question.id}",
        artifacts={
            theory_packet_id: {
                "packet_id": theory_packet_id,
                "theorem_cards": [],
                "estimator_specs": [],
                "simulation_ademp_spec": {"aim": "stress generated simulation drafts"},
            }
        },
    )

    class UnsafeSimulationEngineer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            return {
                "packet_id": "simulation_engineer_proposal:unsafe",
                "simulation_targets": [
                    {
                        "procedure_id": "split_conformal_interval",
                        "estimand": "coverage",
                    }
                ],
                "runtime_execution_plan": {
                    "registered_simulator": "ResearchSimulator.run",
                    "n_runs": 12,
                    "seed": 20260619,
                },
                "critic_findings": [
                    {
                        "critic": "sandbox",
                        "finding": "custom generated simulation needs safe execution",
                        "reroute_if_confirmed": "SimulationEvaluator",
                    }
                ],
                "next_actions": [
                    {
                        "owner_agent": "SimulationEvaluator",
                        "action": "repair generated simulation draft",
                        "acceptance_gate": "generated simulation executes safely",
                    }
                ],
                "simulation_code_drafts": [
                    {
                        "simulation_id": "custom_stress",
                        "language": "python",
                        "entrypoint": "run_sandbox",
                        "code": (
                            "import os\n"
                            "def run_sandbox(seed: int, replicates: int) -> dict:\n"
                            "    return {'sandbox_failed': False, 'cwd': os.getcwd()}\n"
                        ),
                    }
                ],
                "simulation_evidence_status": "LLM_SIMULATION_ENGINEER_PROPOSAL_NOT_EXECUTION_EVIDENCE",
                "simulations_executed": False,
                "proof_evidence_status": "NOT_PROOF_EVIDENCE",
            }

    subsystem = SimulationEvaluatorRuntimeSubsystem(
        proposal_agent=UnsafeSimulationEngineer(),
        sandbox_root=tmp_path / "generated_simulation_sandbox",
    )
    task = AgentTask(
        task_id="simulation:custom",
        owner_subsystem="SimulationEvaluator",
        objective="Repair unsafe generated simulation code.",
        inputs={
            "question": {
                "id": question.id,
                "title": question.title,
                "description": question.description,
                "tags": list(question.tags),
            },
            "theory_packet_id": theory_packet_id,
            "n_runs": 12,
            "seed": 20260619,
            "architect_context": {
                "architect_coordinator_proposal_id": "architect:generated-simulation",
                "architect_runtime_plan": {
                    "problem_analysis": {
                        "theorem_family": "generated simulation smoke target",
                        "statistical_objects": ["generated scalar metric"],
                    },
                    "evidence_contract": {
                        "simulation_targets": ["execute the generated draft"]
                    },
                },
            },
        },
        expected_artifacts=("simulation_manifest",),
    )

    result = subsystem.run(task, blackboard)
    manifest = next(
        artifact
        for key, artifact in result.produced_artifacts.items()
        if key.startswith("simulation_manifest:")
    )

    assert result.status == "REVISE"
    assert result.failure_classification == "generated_simulation_sandbox_no_executable_draft"
    assert manifest["n_generated_simulation_sandbox_prototypes"] == 1
    assert manifest["n_generated_simulation_sandbox_executed"] == 0
    assert manifest["n_unsafe_generated_simulation_code_rejected"] == 1
    assert all(
        not str(row.get("script_path", "")).startswith("runs/")
        for row in manifest["generated_simulation_sandbox_prototypes"]
    )
    summary = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": result.produced_artifacts}}]
    )
    assert summary["simulation"]["n_generated_simulation_sandbox_prototypes"] == 1
    assert summary["simulation"]["n_generated_simulation_sandbox_executed"] == 0
    assert summary["simulation"]["n_unsafe_generated_simulation_code_rejected"] == 1
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "SimulationEvaluator"
    feedback = result.next_task.inputs["environment_feedback"]
    assert feedback["failure_classification"] == "generated_simulation_sandbox_no_executable_draft"
    assert (
        feedback["generated_simulation_prototypes"][0]["prototype_status"]
        == "REJECTED_UNSAFE_GENERATED_CODE"
    )
    assert any(
        "can import only math/statistics" in row
        for row in feedback["generated_simulation_prototypes"][0]["safety_errors"]
    )


