def test_runtime_evidence_summary_counts_structured_theory_derivation_trace() -> None:
    def consumption_contract(consumer: str) -> dict[str, object]:
        return {
            "artifact_kind": "TheoryTraceConsumptionContract",
            "source_theory_packet_id": "theory_derivation:structured",
            "consumer_subsystem": consumer,
            "theory_derivation_trace_supplied": True,
            "n_derivation_steps_supplied": 3,
            "n_equation_chain_steps_supplied": 2,
            "n_assumption_ledger_rows_supplied": 2,
            "has_formalization_handoff": True,
            "boundary": (
                "Theory trace consumption records proposal-context provenance "
                "only; not proof evidence."
            ),
        }

    def alignment_contract(consumer: str) -> dict[str, object]:
        return {
            "artifact_kind": "TheoryTraceAlignmentContract",
            "source_theory_packet_id": "theory_derivation:structured",
            "consumer_subsystem": consumer,
            "llm_alignment_claimed": True,
            "structured_alignment_observed": True,
            "supported_derivation_steps": ["score"],
            "supported_equation_steps": ["expansion"],
            "supported_assumptions": ["positivity"],
            "supported_formalization_targets": ["aipw_asymptotic_normality"],
            "n_supported_anchor_references": 4,
            "n_unsupported_anchor_references": 0,
            "boundary": (
                "Theory trace alignment records proposal-to-trace provenance "
                "only; not proof evidence."
            ),
        }

    artifacts = {
        "theory_derivation:structured": _structured_theory_packet_fixture(),
        "simulation_engineer_proposal:structured": {
            "artifact_kind": "SimulationEngineerProposalPacket",
            "theory_trace_consumption_contract": consumption_contract(
                "SimulationEngineer"
            ),
            "theory_trace_alignment_contract": alignment_contract(
                "SimulationEngineer"
            ),
        },
        "algorithm_engineer_proposal:structured": {
            "artifact_kind": "AlgorithmEngineerProposalPacket",
            "theory_trace_consumption_contract": consumption_contract(
                "AlgorithmEngineer"
            ),
            "theory_trace_alignment_contract": alignment_contract(
                "AlgorithmEngineer"
            ),
        },
        "formalizer_proposal:structured": {
            "artifact_kind": "FormalizerProofEngineerProposalPacket",
            "theory_trace_consumption_contract": consumption_contract(
                "FormalizerProofEngineer"
            ),
            "theory_trace_alignment_contract": alignment_contract(
                "FormalizerProofEngineer"
            ),
        },
    }

    evidence_summary = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": artifacts}}]
    )
    theory = evidence_summary["theory"]

    assert theory["n_theory_derivation_packets"] == 1
    assert theory["n_theory_derivation_packets_with_contract"] == 1
    assert theory["n_theory_derivation_packets_with_min_derivation_steps"] == 1
    assert theory["n_theory_derivation_packets_with_equation_chain"] == 1
    assert theory["n_theory_derivation_packets_with_assumption_ledger"] == 1
    assert theory["n_theory_derivation_packets_with_formalization_handoff"] == 1
    assert theory["max_derivation_steps"] == 3
    assert theory["max_equation_chain_steps"] == 2
    assert theory["structured_derivation_trace_observed"] is True
    assert theory["n_theory_trace_consumption_contracts"] == 3
    assert theory["n_theory_trace_consumption_contracts_with_trace"] == 3
    assert theory["n_theory_trace_consumption_contracts_with_equation_chain"] == 3
    assert theory["n_theory_trace_consumption_contracts_with_assumption_ledger"] == 3
    assert (
        theory["n_theory_trace_consumption_contracts_with_formalization_handoff"]
        == 3
    )
    assert theory["theory_trace_consuming_subsystems"] == [
        "AlgorithmEngineer",
        "FormalizerProofEngineer",
        "SimulationEngineer",
    ]
    assert theory["structured_theory_trace_consuming_subsystems"] == [
        "AlgorithmEngineer",
        "FormalizerProofEngineer",
        "SimulationEngineer",
    ]
    assert theory["all_required_theory_trace_consumers_observed"] is True
    assert theory["n_theory_trace_alignment_contracts"] == 3
    assert theory["n_theory_trace_alignment_contracts_with_llm_alignment"] == 3
    assert theory["n_structured_theory_trace_alignment_contracts"] == 3
    assert theory["n_theory_trace_alignment_contracts_with_unsupported_anchors"] == 0
    assert theory["structured_theory_trace_aligned_subsystems"] == [
        "AlgorithmEngineer",
        "FormalizerProofEngineer",
        "SimulationEngineer",
    ]
    assert (
        theory["all_required_theory_trace_alignment_consumers_observed"]
        is True
    )
    assert "Lean/kernel proof evidence" in theory["theory_trace_alignment_boundary"]
    assert "Lean/kernel proof evidence" in theory["theory_trace_consumption_boundary"]
    assert "not execution or proof evidence" in theory["boundary"]


def test_runtime_evidence_summary_recomputes_stale_alignment_contract() -> None:
    theory_packet = {
        "artifact_kind": "TheoryDerivationPacket",
        "packet_id": "theory_derivation:stale_alignment",
        "theory_derivation_packet": {
            "derivation_steps": [{"id": "D1", "claim": "identify ATE"}],
            "equation_chain": [{"step_id": "EQ1", "lhs": "tau_hat", "rhs": "tau"}],
            "assumption_ledger": [
                {"assumption": "Positivity: eta <= pi(x) <= 1-eta"}
            ],
            "formalization_handoff": {
                "source_theorem_target": "THM1",
                "semantic_alignment_constraints": [
                    (
                        "double-robustness must hold when either pi_hat=pi "
                        "or mu_hat=mu exactly"
                    )
                ],
            },
        },
        "theory_derivation_contract": {
            "min_derivation_steps": 1,
            "n_derivation_steps": 1,
            "n_equation_chain_steps": 1,
            "n_assumption_ledger_rows": 1,
            "has_formalization_handoff": True,
        },
    }
    artifacts = {
        "theory_derivation:stale_alignment": theory_packet,
        "algorithm_engineer_proposal:stale_alignment": {
            "artifact_kind": "AlgorithmEngineerProposalPacket",
            "source_agent": "LLMAlgorithmEngineerAgent",
            "theory_trace_consumption_contract": {
                "artifact_kind": "TheoryTraceConsumptionContract",
                "source_theory_packet_id": "theory_derivation:stale_alignment",
                "consumer_subsystem": "AlgorithmEngineer",
                "theory_derivation_trace_supplied": True,
                "n_derivation_steps_supplied": 1,
                "n_equation_chain_steps_supplied": 1,
                "n_assumption_ledger_rows_supplied": 1,
                "has_formalization_handoff": True,
            },
            "theory_trace_alignment": {
                "referenced_derivation_steps": ["D1: identify ATE"],
                "referenced_equation_steps": ["EQ1: tau_hat expansion"],
                "referenced_assumptions": [
                    "Positivity: eta <= pi(x) <= 1-eta for bounded EIF variance"
                ],
                "referenced_formalization_targets": [
                    "THM1",
                    (
                        "Double-robustness holding when either pi_hat=pi or "
                        "mu_hat=mu exactly"
                    ),
                ],
                "rationale": "descriptive raw alignment from a prior run",
            },
            "theory_trace_alignment_contract": {
                "artifact_kind": "TheoryTraceAlignmentContract",
                "source_theory_packet_id": "theory_derivation:stale_alignment",
                "consumer_subsystem": "AlgorithmEngineer",
                "llm_alignment_claimed": True,
                "structured_alignment_observed": False,
                "supported_assumptions": [],
                "n_unsupported_anchor_references": 5,
            },
        },
    }

    theory = _runtime_evidence_summary(
        [{"blackboard": {"artifacts": artifacts}}]
    )["theory"]

    assert theory["n_theory_trace_alignment_contracts"] == 1
    assert theory["n_structured_theory_trace_alignment_contracts"] == 1
    assert theory["n_theory_trace_alignment_contracts_with_unsupported_anchors"] == 0
    assert (
        theory[
            "n_theory_trace_alignment_contracts_with_historical_unsupported_anchors"
        ]
        == 1
    )
    assert theory["structured_theory_trace_aligned_subsystems"] == [
        "AlgorithmEngineer"
    ]


