        assert "RUNTIME_THEORY_TRACE_DOWNSTREAM_ALIGNMENT_MISSING" in prompt
        assert "THEORY_TRACE_DOWNSTREAM_ALIGNMENT_FEEDBACK_NOT_PROOF_EVIDENCE" in prompt
