def test_source_to_bridge_premise_semantic_repair_feedback_generates_next_action() -> None:
    feedback_row = {
        "schema_version": 1,
        "learning_task": "source_to_bridge_premise_semantic_repair_feedback",
        "question_id": "conformal_prediction_coverage",
        "target_theorem_name": "split_conformal_coverage",
        "work_order_id": "source_theorem_semantic_primitive_work_order:hGoodCovered",
        "semantic_primitive_id": (
            "source_to_bridge_premise_semantic_gap:"
            "split_conformal_coverage:hGoodCovered"
        ),
        "semantic_primitive_gap_kind": "source_to_bridge_premise_semantic_gap",
        "premise_name": "hGoodCovered",
        "premise_target_status": "ADAPTER_PREMISE_TARGET_EXTRACTED",
        "premise_target_type": "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered",
        "premise_derivation_gap_kind": (
            "concrete_premise_target_lacks_nonvacuous_derivation_candidate"
        ),
        "premise_derivation_gap_summary": (
            "The adapter premise target is known, but the bridge only "
            "materialized a non-evidence skeleton."
        ),
        "runtime_queue_status": "PENDING_SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR",
        "proof_evidence_status": (
            "SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR_FEEDBACK_NOT_PROOF_EVIDENCE"
        ),
    }
    agenda_rows: list[dict[str, object]] = []

    generated_rows = _append_runtime_generated_next_action_rows(
        agenda_rows,
        [feedback_row],
        queue_name="source_theorem_semantic_primitive_proofengineer_bridge",
    )

    assert len(generated_rows) == 1
    generated_row = generated_rows[0]
    assert generated_row["trigger"] == "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP"
    assert generated_row["owner_subsystem"] == (
        "TheoryDeveloper/Formalizer/ProofEngineer"
    )
    assert generated_row["premise_name"] == "hGoodCovered"
    assert generated_row["premise_target_status"] == (
        "ADAPTER_PREMISE_TARGET_EXTRACTED"
    )
    assert generated_row["premise_target_type"] == (
        "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered"
    )
    assert "route upstream to TheoryDeveloper/Formalizer" in generated_row["action"]


def test_generated_premise_gap_next_actions_drive_formalizer_and_critic_route() -> None:
    feedback_rows = [
        {
            "schema_version": 1,
            "learning_task": "source_to_bridge_premise_semantic_repair_feedback",
            "question_id": "conformal_prediction_coverage",
            "target_theorem_name": "split_conformal_coverage",
            "work_order_id": f"source_theorem_semantic_primitive_work_order:{name}",
            "semantic_primitive_id": (
                "source_to_bridge_premise_semantic_gap:"
                f"split_conformal_coverage:{name}"
            ),
            "semantic_primitive_gap_kind": "source_to_bridge_premise_semantic_gap",
            "premise_name": name,
            "premise_target_status": "ADAPTER_PREMISE_TARGET_EXTRACTED",
            "premise_target_type": target,
            "premise_derivation_gap_kind": (
                "concrete_premise_target_lacks_nonvacuous_derivation_candidate"
            ),
            "premise_derivation_gap_summary": (
                "Concrete target known but no non-vacuous derivation candidate."
            ),
            "proof_evidence_status": (
                "SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR_FEEDBACK_NOT_PROOF_EVIDENCE"
            ),
        }
        for name, target in [
            ("hGoodCovered", "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered"),
            ("hRank", "∀ r ∈ BadRanks, P {ω | rank ω = r} ≤ α r"),
        ]
    ]
    generated_rows: list[dict[str, object]] = []

    _append_runtime_generated_next_action_rows(
        generated_rows,
        feedback_rows,
        queue_name="source_theorem_semantic_primitive_proofengineer_bridge",
    )

    assert [
        row["premise_name"] for row in generated_rows
    ] == ["hGoodCovered", "hRank"]
    assert (
        _runtime_source_theorem_semantic_primitive_work_order_rows_from_learning_rows(
            generated_rows
        )
        == []
    )
    memory = {
        "artifact_kind": "RuntimeLearningMemoryContext",
        "rows": generated_rows,
    }
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=[],
        theorem_goals=[],
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["source_to_bridge_premise_derivation_required"] is True
    assert summary["source_to_bridge_premise_derivation_pending_premise_names"] == [
        "hGoodCovered",
        "hRank",
    ]
    diagnostics = summary["source_to_bridge_premise_derivation_diagnostics"]
    assert [row["premise_name"] for row in diagnostics] == [
        "hGoodCovered",
        "hRank",
    ]
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    agenda = _critic_next_action_agenda(
        question=question,
        retrieval_manifest={},
        theory_packet={},
        simulation_manifest={},
        algorithm_manifest={},
        formalization_manifest={
            "counts": {"formal_gap": 1},
            "proof_bank_runtime_memory_summary": summary,
            "deterministic_theorem_goals": [
                {"id": "split_conformal_finite_sample_coverage"}
            ],
        },
    )

    assert agenda[0]["id"] == "formal_gap:source_to_bridge_premise_derivation"
    assert agenda[0]["trigger"] == "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_GAP"
    assert agenda[0]["premise_names"] == ["hGoodCovered", "hRank"]


def test_critic_agenda_kernel_rerun_preserves_target_ids() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]

    agenda = _critic_next_action_agenda(
        question=question,
        retrieval_manifest={"counts": {"formal_source_hits": 1}},
        theory_packet={"packet_id": "theory:conformal"},
        simulation_manifest={"simulation_passed": True},
        algorithm_manifest={"n_executed": 0},
        formalization_manifest={
            "counts": {
                "formal_gap": 1,
                "proved": 1,
                "kernel_verified": 0,
            },
            "deterministic_theorem_goals": [
                {"id": "split_conformal_finite_sample_coverage"}
            ],
        },
    )

    kernel_rerun = next(
        row for row in agenda if row["id"] == "proof_feedback:kernel_rerun"
    )
    assert kernel_rerun["target_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]

    summary = _runtime_target_identity_audit_summary(
        learning_rows=[],
        agenda_rows=agenda,
    )
    assert summary["n_runtime_route_critical_rows_missing_target_ids"] == 0


def test_grouped_source_to_bridge_premise_request_is_first_class_memory(
    tmp_path: Path,
) -> None:
    grouped_request = {
        "grouped_candidate_request_id": (
            "source_to_bridge_grouped_premise_derivation_candidate_request:shared"
        ),
        "adapter_instantiation_group_id": (
            "source_to_bridge_adapter_instantiation_group:shared"
        ),
        "premise_names": ["hGoodCovered", "hBadEvent", "hRank", "h_total"],
        "required_bridge_premise_names_for_shared_instantiation": [
            "hGoodCovered",
            "hBadEvent",
            "hRank",
            "h_total",
        ],
        "target_theorem_name": "split_conformal_coverage",
        "target_lean_declaration": "split_conformal_coverage",
        "adapter_object_names_requiring_source_instantiation": [
            "covered",
            "rank",
            "BadRanks",
            "alpha",
            "alpha_total",
        ],
        "premise_candidate_declaration_names": [
            {
                "premise_name": "hGoodCovered",
                "premise_candidate_declaration_name": (
                    "split_conformal_coverage_hGoodCovered_source_to_bridge_derivation"
                ),
            },
            {
                "premise_name": "hBadEvent",
                "premise_candidate_declaration_name": (
                    "split_conformal_coverage_hBadEvent_source_to_bridge_derivation"
                ),
            },
            {
                "premise_name": "hRank",
                "premise_candidate_declaration_name": (
                    "split_conformal_coverage_hRank_source_to_bridge_derivation"
                ),
            },
            {
                "premise_name": "h_total",
                "premise_candidate_declaration_name": (
                    "split_conformal_coverage_h_total_source_to_bridge_derivation"
                ),
            },
        ],
        "exact_source_theorem_binders": [
            {"name": "hexch", "type": "Prop", "role": "exchangeability_anchor"},
            {"name": "hq", "type": "Prop", "role": "quantile_definition_anchor"},
            {"name": "hC", "type": "Prop", "role": "coverage_event_anchor"},
        ],
        "premise_semantic_anchor_binders": [
            {"name": "hexch", "type": "Prop", "role": "exchangeability_anchor"},
            {"name": "hq", "type": "Prop", "role": "quantile_definition_anchor"},
            {"name": "hC", "type": "Prop", "role": "coverage_event_anchor"},
        ],
        "premise_semantic_anchor_binder_names": ["hexch", "hq", "hC"],
        "required_semantic_anchor_reference_names": ["hexch", "hq", "hC"],
        "shared_adapter_instantiation_contract": (
            "Use one source-derived covered/rank/BadRanks/alpha/alpha_total instantiation."
        ),
        "candidate_contract": (
            "Return one source_to_bridge_premise_derivation_candidates object "
            "for this group. The proof body must substantively reference every "
            "required_semantic_anchor_reference_names entry outside comments and "
            "outside no-op lines such as `have h := h`."
        ),
        "forbidden_actions": [
            "do not split this group into incompatible adapter-object definitions",
            "do not satisfy semantic-anchor requirements with comments or unused have/let aliases",
            "do not put adapter objects such as covered, rank, BadRanks, alpha, or alpha_total in the theorem header as free binders",
        ],
        "proof_evidence_status": (
            "SOURCE_TO_BRIDGE_GROUPED_PREMISE_DERIVATION_CANDIDATE_REQUEST_NOT_PROOF_EVIDENCE"
        ),
    }
    memory = {
        "artifact_kind": "RuntimeLearningMemoryContext",
        "rows": [
            {
                "learning_task": (
                    "source_to_bridge_grouped_premise_derivation_candidate_request"
                ),
                "question_id": "conformal_prediction_coverage",
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "premise_names": ["hGoodCovered", "hBadEvent", "hRank", "h_total"],
                "source_to_bridge_grouped_premise_derivation_candidate_request_id": (
                    grouped_request["grouped_candidate_request_id"]
                ),
                "source_to_bridge_grouped_premise_derivation_candidate_request": (
                    grouped_request
                ),
                "runtime_queue_status": (
                    "PENDING_GROUPED_SOURCE_TO_BRIDGE_PREMISE_DERIVATION"
                ),
                "proof_evidence_status": grouped_request["proof_evidence_status"],
            }
        ],
    }
    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(
        json.dumps(memory["rows"][0]) + "\n",
        encoding="utf-8",
    )
    loaded_memory = _load_runtime_learning_memory([learning_path], max_rows=8)
    loaded_row = loaded_memory["rows"][0]
    assert loaded_row[
        "source_to_bridge_grouped_premise_derivation_candidate_request_id"
    ] == grouped_request["grouped_candidate_request_id"]
    loaded_grouped_request = loaded_row[
        "source_to_bridge_grouped_premise_derivation_candidate_request"
    ]
    assert loaded_grouped_request["premise_names"] == [
        "hGoodCovered",
        "hBadEvent",
        "hRank",
        "h_total",
    ]
    assert loaded_grouped_request[
        "adapter_object_names_requiring_source_instantiation"
    ] == ["covered", "rank", "BadRanks", "alpha", "alpha_total"]
    assert "substantively reference every" in loaded_grouped_request[
        "candidate_contract"
    ]
    assert (
        "do not put adapter objects such as covered, rank, BadRanks, alpha, or alpha_total in the theorem header as free binders"
        in loaded_grouped_request["forbidden_actions"]
    )

    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": loaded_memory},
        proof_bank_obligation_catalog=[],
        theorem_goals=[],
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["recommended_formalizer_target_mode"] == (
        "source_to_bridge_premise_derivation_required"
    )
    assert summary["source_to_bridge_premise_derivation_required"] is True
    assert summary["source_to_bridge_premise_derivation_pending_premise_names"] == [
        "hGoodCovered",
        "hBadEvent",
        "hRank",
        "h_total",
    ]
    diagnostic = summary["source_to_bridge_premise_derivation_diagnostics"][0]
    assert diagnostic["premise_names"] == [
        "hGoodCovered",
        "hBadEvent",
        "hRank",
        "h_total",
    ]
    assert diagnostic[
        "source_to_bridge_grouped_premise_derivation_candidate_request_id"
    ] == grouped_request["grouped_candidate_request_id"]
    assert diagnostic[
        "source_to_bridge_grouped_premise_derivation_candidate_request"
    ]["premise_names"] == ["hGoodCovered", "hBadEvent", "hRank", "h_total"]
    grouped_diagnostic_request = diagnostic[
        "source_to_bridge_grouped_premise_derivation_candidate_request"
    ]
    assert "substantively reference every" in grouped_diagnostic_request[
        "candidate_contract"
    ]
    assert (
        "do not satisfy semantic-anchor requirements with comments or unused have/let aliases"
        in grouped_diagnostic_request["forbidden_actions"]
    )

    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet={"packet_id": "theory:test", "formalization_requests": []},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1},
        registered_problem={"problem_class": "conformal_prediction"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary=summary,
    )
    assert "source_to_bridge_grouped_premise_derivation_candidate_request" in prompt
    assert "substantively reference every" in prompt
    assert (
        "do not satisfy semantic-anchor requirements with comments or unused have/let aliases"
        in prompt
    )
    assert "do not put adapter objects such as covered, rank, BadRanks" in prompt

    proposal = {
        "packet_id": "formalizer_proposal:grouped_premise_derivation",
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_names": ["hGoodCovered", "hBadEvent", "hRank", "h_total"],
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "premise_derivation_candidate_lean_source": (
                    "import Mathlib\n\n"
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    "(hexch hq hC : Prop) : True := by\n"
                    "  trivial\n"
                    "theorem split_conformal_coverage_hBadEvent_source_to_bridge_derivation "
                    "(hexch hq hC : Prop) : True := by\n"
                    "  trivial\n"
                    "theorem split_conformal_coverage_hRank_source_to_bridge_derivation "
                    "(hexch hq hC : Prop) : True := by\n"
                    "  trivial\n"
                    "theorem split_conformal_coverage_h_total_source_to_bridge_derivation "
                    "(hexch hq hC : Prop) : True := by\n"
                    "  trivial"
                ),
            }
        ],
    }

    work_orders = _formalizer_source_to_bridge_premise_derivation_work_orders(
        proposal_packet=proposal,
        proof_bank_runtime_memory_summary=summary,
        theorem_goals=[],
    )

    assert [row["premise_name"] for row in work_orders] == [
        "hGoodCovered",
        "hBadEvent",
        "hRank",
        "h_total",
    ]
    assert {
        row["source_to_bridge_grouped_premise_derivation_candidate_request_id"]
        for row in work_orders
    } == {grouped_request["grouped_candidate_request_id"]}
    assert all(
        row["source_to_bridge_grouped_premise_derivation_candidate_request"][
            "adapter_instantiation_group_id"
        ]
        == grouped_request["adapter_instantiation_group_id"]
        for row in work_orders
    )
    assert all(
        row["required_bridge_premise_names_for_shared_instantiation"]
        == ["hGoodCovered", "hBadEvent", "hRank", "h_total"]
        for row in work_orders
    )
    assert all(
        row["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"
        for row in work_orders
    )


def test_source_to_bridge_premise_candidate_without_source_contract_is_not_queued() -> None:
    proposal = {
        "packet_id": "formalizer_proposal:missing_source_contract",
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_names": ["hGoodCovered", "hBadEvent"],
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "adapter_instantiation_group_id": (
                    "conformal_rank_covered_adapter_group"
                ),
                "premise_derivation_candidate_lean_source": (
                    "import Mathlib\n\n"
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    "(source_hypotheses : Prop) (h : source_hypotheses) : True := by\n"
                    "  trivial\n"
                    "theorem split_conformal_coverage_hBadEvent_source_to_bridge_derivation "
                    "(source_hypotheses : Prop) (h : source_hypotheses) : True := by\n"
                    "  trivial"
                ),
            }
        ],
    }
    summary = {
        "recommended_formalizer_target_mode": (
            "source_to_bridge_premise_derivation_required"
        ),
        "source_to_bridge_premise_derivation_required": True,
        "source_to_bridge_premise_derivation_pending_premise_names": [
            "hGoodCovered",
            "hBadEvent",
        ],
        "source_to_bridge_premise_derivation_diagnostics": [
            {
                "premise_names": ["hGoodCovered", "hBadEvent"],
                "adapter_instantiation_group_id": (
                    "conformal_rank_covered_adapter_group"
                ),
            }
        ],
    }

    work_orders = _formalizer_source_to_bridge_premise_derivation_work_orders(
        proposal_packet=proposal,
        proof_bank_runtime_memory_summary=summary,
        theorem_goals=[],
    )

    assert work_orders == []


def test_source_to_bridge_feedback_source_candidate_request_promotes_to_formalizer_summary(
    tmp_path: Path,
) -> None:
    source_request = {
        "candidate_request_id": (
            "source_to_bridge_premise_derivation_candidate_request:hGoodCovered"
        ),
        "premise_name": "hGoodCovered",
        "target_theorem_name": "split_conformal_coverage",
        "target_lean_declaration": "split_conformal_coverage",
        "premise_candidate_declaration_name": (
            "split_conformal_coverage_hGoodCovered_source_to_bridge_derivation"
        ),
        "premise_semantic_anchor_binder_names": ["n2", "hn2", "hq", "C"],
        "required_semantic_anchor_reference_names": ["n2", "hn2", "hq", "C"],
        "adapter_object_names_requiring_source_instantiation": [
            "covered",
            "rank",
            "BadRanks",
        ],
        "candidate_contract": (
            "Repair the candidate to reference n2, hn2, hq, and C outside comments."
        ),
        "proof_evidence_status": (
            "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_CANDIDATE_REQUEST_NOT_PROOF_EVIDENCE"
        ),
    }
    learning_row = {
        "schema_version": 1,
        "learning_task": "source_to_bridge_premise_derivation_feedback",
        "question_id": "conformal_prediction_coverage",
        "target_theorem_name": "split_conformal_coverage",
        "target_lean_declaration": "split_conformal_coverage",
        "premise_name": "hGoodCovered",
        "failure_classification": (
            "premise_derivation_candidate_missing_semantic_anchor_reference"
        ),
        "premise_derivation_gap_kind": (
            "premise_derivation_missing_semantic_anchor_reference"
        ),
        "premise_derivation_gap_summary": (
            "Candidate missed required source anchors n2, hn2, hq, C."
        ),
        "missing_premise_semantic_anchor_binder_names": [
            "n2",
            "hn2",
            "hq",
            "C",
        ],
        "source_to_bridge_premise_derivation_source_candidate_request_id": (
            source_request["candidate_request_id"]
        ),
        "source_to_bridge_premise_derivation_source_candidate_request": source_request,
        "proof_evidence_status": (
            "SOURCE_TO_BRIDGE_PREMISE_DERIVATION_BRIDGE_NOT_PROOF_EVIDENCE"
        ),
    }
    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(json.dumps(learning_row) + "\n", encoding="utf-8")

    memory = _load_runtime_learning_memory([learning_path], max_rows=4)
    loaded_row = memory["rows"][0]
    assert loaded_row[
        "source_to_bridge_premise_derivation_source_candidate_request_id"
    ] == source_request["candidate_request_id"]
    assert loaded_row[
        "source_to_bridge_premise_derivation_source_candidate_request"
    ]["required_semantic_anchor_reference_names"] == ["n2", "hn2", "hq", "C"]

    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=[],
        theorem_goals=[],
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    diagnostic = summary["source_to_bridge_premise_derivation_diagnostics"][0]
    assert diagnostic[
        "source_to_bridge_premise_derivation_candidate_request_id"
    ] == source_request["candidate_request_id"]
    assert diagnostic[
        "source_to_bridge_premise_derivation_candidate_request"
    ]["candidate_contract"].startswith("Repair the candidate")
    assert diagnostic[
        "source_to_bridge_premise_derivation_candidate_request"
    ]["required_semantic_anchor_reference_names"] == ["n2", "hn2", "hq", "C"]
    assert diagnostic["required_semantic_anchor_reference_names"] == [
        "n2",
        "hn2",
        "hq",
        "C",
    ]


def test_premise_semantic_repair_feedback_exports_covered_semantic_definition_work_order() -> None:
    feedback_row = {
        "schema_version": 1,
        "learning_task": "source_to_bridge_premise_semantic_repair_feedback",
        "question_id": "conformal_prediction_coverage",
        "target_theorem_name": "split_conformal_coverage",
        "work_order_id": "source_theorem_semantic_primitive_work_order:hGoodCovered",
        "semantic_primitive_id": (
            "source_to_bridge_premise_semantic_gap:"
            "split_conformal_coverage:hGoodCovered"
        ),
        "semantic_primitive_gap_kind": "source_to_bridge_premise_semantic_gap",
        "premise_name": "hGoodCovered",
        "premise_target_status": "ADAPTER_PREMISE_TARGET_EXTRACTED",
        "premise_target_type": "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered",
        "premise_derivation_gap_kind": (
            "concrete_premise_target_lacks_nonvacuous_derivation_candidate"
        ),
        "premise_derivation_gap_summary": (
            "Concrete target known but no non-vacuous derivation candidate."
        ),
        "premise_semantic_dependency_requirements": [
            "define covered from the exact source coverage event using hC",
            "prove good-rank containment after covered is source-instantiated",
        ],
        "exact_source_theorem_binders": [
            {"name": "hq", "type": "q_hat = fun ω => orderStat s k ω"},
            {
                "name": "hC",
                "type": (
                    "∀ ω, C ω = {y | s (Fin.last n2) ω ≤ q_hat ω}"
                ),
            },
        ],
        "premise_semantic_anchor_binder_names": ["hq", "hC"],
        "required_semantic_anchor_reference_names": ["hq", "hC"],
        "missing_premise_semantic_anchor_binder_names": ["hq", "hC"],
        "runtime_queue_status": "PENDING_SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR",
        "proof_evidence_status": (
            "SOURCE_TO_BRIDGE_PREMISE_SEMANTIC_REPAIR_FEEDBACK_NOT_PROOF_EVIDENCE"
        ),
    }

    work_orders = (
        _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_semantic_alignment_learning_rows(
            [feedback_row]
        )
    )

    assert len(work_orders) == 1
    work_order = work_orders[0]
    assert work_order["artifact_kind"] == (
        "RuntimeSourceTheoremExactSemanticDefinitionWorkOrder"
    )
    assert work_order["placeholder_symbol"] == "covered"
    assert work_order["placeholder_symbol"] != "hGoodCovered"
    assert work_order["premise_name"] == "hGoodCovered"
    assert work_order["premise_target_type"] == (
        "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered"
    )
    assert work_order["premise_semantic_anchor_binder_names"] == ["hq", "hC"]
    assert work_order["required_semantic_anchor_reference_names"] == ["hq", "hC"]
    assert work_order["missing_premise_semantic_anchor_binder_names"] == [
        "hq",
        "hC",
    ]
    assert work_order["runtime_queue_status"] == (
        "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_REPAIR"
    )
    assert work_order["source_theorem_ready_for_exact_proof_body"] is False
    assert work_order["source_theorem_semantic_support_only"] is True
    assert "hC" in " ".join(work_order["search_targets"])
    assert work_order["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"


