def test_exact_semantic_definition_work_orders_from_semantic_alignment_feedback(
    tmp_path: Path,
) -> None:
    learning_rows = [
        {
            "schema_version": 1,
            "learning_task": "exact_source_theorem_proof_body_execution_feedback",
            "trigger": "EXACT_SOURCE_SEMANTIC_ALIGNMENT_REVIEW_REQUIRED",
            "question_id": "conformal_prediction_coverage",
            "target_theorem_name": "split_conformal_coverage",
            "target_lean_declaration": "split_conformal_coverage",
            "source_work_order_id": "exact_source_work_order:semantic_alignment",
            "execution_result_id": "exact_source_execution_result:semantic_alignment",
            "source_theorem_target_known": False,
            "source_theorem_target_identity_status": (
                "DECLARATION_MATCHED_SOURCE_THEOREM_TARGET_UNPROMOTED"
            ),
            "source_theorem_target_provenance": {
                "source_theorem_question_id": "conformal_prediction_coverage",
                "target_lean_declaration": "split_conformal_coverage",
            },
            "semantic_alignment_blockers": [
                "unreviewed synthesized definition semantic risk: "
                "draft pairwise order-probability symmetry is weaker than full "
                "finite permutation-invariant joint-law exchangeability",
                "unreviewed synthesized definition semantic risk: "
                "draft finite maximum ignores rank k and is not a reviewed "
                "conformal quantile/order-statistic definition",
            ],
            "input_summary": {
                "failure_classification": (
                    "source_theorem_semantic_alignment_unreviewed"
                ),
                "target_theorem_name": "split_conformal_coverage",
                "candidate_artifact_path": "runs/candidate.lean",
            },
        }
    ]

    work_orders = (
        _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_semantic_alignment_learning_rows(
            learning_rows
        )
    )

    assert {row["placeholder_symbol"] for row in work_orders} == {
        "Exchangeable",
        "orderStat",
    }
    assert all(
        row["artifact_kind"]
        == "RuntimeSourceTheoremExactSemanticDefinitionWorkOrder"
        for row in work_orders
    )
    assert all(
        row["source_semantic_alignment_review_required"] is True
        for row in work_orders
    )
    assert all(
        row["source_theorem_target_identity_status"]
        == "DECLARATION_MATCHED_SOURCE_THEOREM_TARGET_UNPROMOTED"
        for row in work_orders
    )
    assert all(
        len(row["semantic_alignment_blockers"]) == 2
        for row in work_orders
    )
    assert all(row["source_theorem_semantic_support_only"] is True for row in work_orders)
    assert all(
        row["source_theorem_ready_for_exact_proof_body"] is False
        for row in work_orders
    )
    assert {
        tuple(row["candidate_registered_obligation_ids"]) for row in work_orders
    } == {
        ("split_conformal_bad_rank_budget_from_uniform_rank_bound",),
        ("split_conformal_good_rank_set_inclusion_bridge",),
    }

    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(
        "\n".join(
            json.dumps(row)
            for row in _runtime_source_theorem_exact_semantic_definition_learning_rows(
                work_orders
            )
        )
        + "\n",
        encoding="utf-8",
    )
    memory = _load_runtime_learning_memory([learning_path])
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )
    assert summary["source_theorem_exact_candidate_requires_repair"] is True
    assert {
        diagnostic["source_theorem_target_identity_status"]
        for diagnostic in summary["source_theorem_exact_candidate_repair_diagnostics"]
        if diagnostic.get("source_theorem_target_identity_status")
    } == {"DECLARATION_MATCHED_SOURCE_THEOREM_TARGET_UNPROMOTED"}
    assert {
        blocker
        for diagnostic in summary["source_theorem_exact_candidate_repair_diagnostics"]
        for blocker in diagnostic["semantic_alignment_blockers"]
    } == set(learning_rows[0]["semantic_alignment_blockers"])
    assert {
        row["placeholder_symbol"]
        for row in summary["source_theorem_exact_candidate_placeholder_resolution_plan"]
    } == {"Exchangeable", "orderStat"}


def test_exact_semantic_definition_work_orders_retarget_stale_candidate_request() -> None:
    seed_rows = [
        {
            "materialization_seed_status": (
                "BLOCKED_NEEDS_REVIEWED_EXACT_SEMANTIC_DEFINITIONS"
            ),
            "materialization_seed_id": "seed:stale-candidate-request",
            "question_id": "conformal_prediction_coverage",
            "target_theorem_name": "split_conformal_finite_sample_coverage",
            "target_ids": ["split_conformal_finite_sample_coverage"],
            "source_theorem_exact_candidate_placeholder_resolution_plan": [
                {
                    "placeholder_symbol": "C_n",
                    "replacement_strategy": "define the conformal threshold object",
                    "search_targets": ["conformal threshold"],
                },
                {
                    "placeholder_symbol": "Exchangeable",
                    "replacement_strategy": "define exchangeability of scores",
                    "search_targets": ["exchangeable finite family"],
                },
                {
                    "placeholder_symbol": "orderStat",
                    "replacement_strategy": "define finite order statistic",
                    "search_targets": ["finite order statistic"],
                },
            ],
            "candidate_definition_request": {
                "request_kind": "source_theorem_exact_semantic_definition_candidate",
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "placeholder_symbol": "C_n",
                "semantic_goal": "Define C_n from the order-statistic quantile rule.",
                "required_anchor_names": [
                    "hQuantileThreshold",
                    "hGoodRank",
                    "hExch",
                ],
                "required_adapter_object_names": ["C_n"],
                "available_adapter_object_names": [
                    "coverage_event",
                    "good_rank_event",
                    "C_n",
                ],
                "source_to_bridge_adapter_instantiation_group_id": (
                    "split_conformal_coverage_adapter_v6"
                ),
                "required_bridge_premise_names_for_shared_instantiation": [
                    "hGoodRankImpliesCovered",
                    "hQuantileThreshold",
                ],
                "proof_evidence_status": (
                    "ADAPTER_OBJECT_SEMANTIC_DEFINITION_WORK_ORDER_NOT_PROOF_EVIDENCE"
                ),
            },
        }
    ]

    work_orders = _runtime_source_theorem_exact_semantic_definition_work_order_rows(
        seed_rows
    )

    rows_by_symbol = {row["placeholder_symbol"]: row for row in work_orders}
    assert set(rows_by_symbol) == {"C_n", "Exchangeable", "orderStat"}
    assert rows_by_symbol["C_n"]["candidate_definition_request"][
        "placeholder_symbol"
    ] == "C_n"
    assert rows_by_symbol["C_n"]["candidate_definition_request"][
        "required_adapter_object_names"
    ] == ["C_n"]
    for symbol in ("Exchangeable", "orderStat"):
        request = rows_by_symbol[symbol]["candidate_definition_request"]
        assert request["placeholder_symbol"] == symbol
        assert request["source_candidate_definition_request_placeholder_symbol"] == "C_n"
        assert request["source_candidate_definition_request_was_retargeted"] is True
        assert request["source_candidate_definition_request"][
            "placeholder_symbol"
        ] == "C_n"
        assert "semantic_goal" not in request
        assert request.get("required_adapter_object_names") != ["C_n"]

    learning_rows = _runtime_source_theorem_exact_semantic_definition_learning_rows(
        work_orders
    )
    learning_by_symbol = {
        row["placeholder_symbol"]: row
        for row in learning_rows
    }
    for symbol in ("Exchangeable", "orderStat"):
        assert learning_by_symbol[symbol]["candidate_definition_request"][
            "placeholder_symbol"
        ] == symbol
        assert learning_by_symbol[symbol]["input_summary"][
            "candidate_definition_request"
        ]["placeholder_symbol"] == symbol

    legacy_replay_row = dict(rows_by_symbol["Exchangeable"])
    legacy_replay_row["candidate_definition_request"] = dict(
        seed_rows[0]["candidate_definition_request"]
    )
    legacy_replay_row["input_summary"] = {
        "target_theorem_name": "split_conformal_finite_sample_coverage",
        "placeholder_symbol": "Exchangeable",
        "candidate_definition_request": dict(seed_rows[0]["candidate_definition_request"]),
    }
    replayed_rows = (
        _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_learning_rows(
            [legacy_replay_row]
        )
    )
    assert len(replayed_rows) == 1
    replayed_request = replayed_rows[0]["candidate_definition_request"]
    assert replayed_request["placeholder_symbol"] == "Exchangeable"
    assert (
        replayed_request["source_candidate_definition_request_placeholder_symbol"]
        == "C_n"
    )
    assert replayed_request["source_candidate_definition_request_was_retargeted"] is True
    assert replayed_request.get("required_adapter_object_names") != ["C_n"]


