def test_runtime_learning_memory_loader_preserves_authoring_retry_request(
    tmp_path: Path,
) -> None:
    learning_path = tmp_path / "authoring_retry_learning_rows.jsonl"
    learning_path.write_text(
        json.dumps(
            {
                "schema_version": 1,
                "artifact_kind": "SourceTheoremExactSemanticDefinitionAuthoringLearningRow",
                "learning_task": (
                    "source_theorem_exact_semantic_definition_authoring_worker"
                ),
                "question_id": "conformal_prediction_coverage",
                "target_theorem_name": "split_conformal_coverage",
                "placeholder_symbol": "rank",
                "runtime_queue_status": (
                    "PENDING_EXACT_SEMANTIC_DEFINITION_AUTHORING_RETRY"
                ),
                "failure_classification": "provider_connection_error",
                "recommended_next_action": (
                    "retry the same exact semantic-definition authoring prompt"
                ),
                "candidate_definition_request": {
                    "request_kind": "source_theorem_exact_semantic_definition_candidate",
                    "target_theorem_name": "split_conformal_coverage",
                    "placeholder_symbol": "rank",
                    "semantic_goal": (
                        "Define the rank object from hq and the score process"
                    ),
                    "required_anchor_names": ["n2", "s", "q_hat", "hq"],
                    "available_anchor_names": [
                        "n2",
                        "hn2",
                        "alpha",
                        "halpha",
                        "s",
                        "q_hat",
                        "hq",
                        "C",
                        "P",
                        "hexch",
                    ],
                    "missing_required_anchor_names": [],
                    "required_binders": [
                        {"name": "n2", "role": "calibration_size_anchor"},
                        {"name": "s", "role": "score_process_anchor"},
                        {"name": "q_hat", "role": "threshold_function_anchor"},
                        {"name": "hq", "role": "quantile_definition_anchor"},
                    ],
                    "proof_evidence_status": (
                        "EXACT_SEMANTIC_DEFINITION_AUTHORING_TASK_NOT_PROOF_EVIDENCE"
                    ),
                },
                "input_summary": {
                    "trigger": "EXACT_SEMANTIC_DEFINITION_AUTHORING_CANDIDATE_PACKET",
                    "runtime_queue_status": (
                        "PENDING_EXACT_SEMANTIC_DEFINITION_AUTHORING_RETRY"
                    ),
                    "failure_classification": "provider_connection_error",
                    "candidate_definition_request": {
                        "request_kind": (
                            "source_theorem_exact_semantic_definition_candidate"
                        ),
                        "target_theorem_name": "split_conformal_coverage",
                        "placeholder_symbol": "rank",
                        "required_anchor_names": ["n2", "s", "q_hat", "hq"],
                        "missing_required_anchor_names": [],
                    },
                    "exact_source_theorem_binders": [
                        {"name": "P", "role": "source_measure_anchor"},
                        {"name": "hexch", "role": "exchangeability_anchor"},
                    ],
                },
                "exact_source_theorem_binders": [
                    {"name": "P", "role": "source_measure_anchor"},
                    {"name": "hexch", "role": "exchangeability_anchor"},
                ],
                "premise_semantic_anchor_binders": [
                    {"name": "hq", "role": "quantile_definition_anchor"},
                ],
                "source_to_bridge_adapter_object_names_requiring_source_instantiation": [
                    "rank",
                    "BadRanks",
                ],
                "proof_evidence_status": (
                    "EXACT_SEMANTIC_DEFINITION_AUTHORING_CANDIDATE_NOT_PROOF_EVIDENCE"
                ),
            }
        )
        + "\n",
        encoding="utf-8",
    )

    memory = _load_runtime_learning_memory([learning_path])

    row = memory["rows"][0]
    assert row["runtime_queue_status"] == (
        "PENDING_EXACT_SEMANTIC_DEFINITION_AUTHORING_RETRY"
    )
    assert row["failure_classification"] == "provider_connection_error"
    assert row["candidate_definition_request"]["placeholder_symbol"] == "rank"
    assert row["candidate_definition_request"]["required_anchor_names"] == [
        "n2",
        "s",
        "q_hat",
        "hq",
    ]
    assert "P" in row["candidate_definition_request"]["available_anchor_names"]
    assert "hexch" in row["candidate_definition_request"]["available_anchor_names"]
    assert row["candidate_definition_request"]["missing_required_anchor_names"] == []
    assert [item["name"] for item in row["exact_source_theorem_binders"]] == [
        "P",
        "hexch",
    ]
    assert [item["name"] for item in row["premise_semantic_anchor_binders"]] == [
        "hq",
    ]
    assert row[
        "source_to_bridge_adapter_object_names_requiring_source_instantiation"
    ] == ["rank", "BadRanks"]
    assert row["input_summary"]["candidate_definition_request"][
        "placeholder_symbol"
    ] == "rank"

    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["source_theorem_exact_candidate_requires_repair"] is True
    assert summary[
        "source_theorem_exact_semantic_definition_authoring_retry_required"
    ] is True
    assert "EXACT_SOURCE_SEMANTIC_DEFINITION_AUTHORING_RETRY" in summary[
        "source_theorem_exact_candidate_repair_triggers"
    ]
    retry_diagnostic = summary["source_theorem_exact_candidate_repair_diagnostics"][0]
    assert retry_diagnostic["failure_classification"] == "provider_connection_error"
    assert retry_diagnostic["runtime_queue_status"] == (
        "PENDING_EXACT_SEMANTIC_DEFINITION_AUTHORING_RETRY"
    )
