def test_selects_latest_available_proof_body_queue_manifest_for_semantic_recheck(
    tmp_path: Path,
) -> None:
    initial = tmp_path / "initial_queue_manifest.json"
    source_semantic = tmp_path / "source_semantic_queue_manifest.json"
    post_executor = tmp_path / "post_executor_queue_manifest.json"
    initial.write_text("{}", encoding="utf-8")
    source_semantic.write_text("{}", encoding="utf-8")
    post_executor.write_text("{}", encoding="utf-8")

    selected = _proof_body_execution_queue_manifest_from_bridge_manifests(
        {"proof_body_execution_queue_manifest": str(post_executor)},
        {"proof_body_execution_queue_manifest": str(source_semantic)},
        {"proof_body_execution_queue_manifest": str(initial)},
    )

    assert selected == post_executor
    assert _proof_body_execution_queue_manifest_from_bridge_manifests(
        {"proof_body_execution_queue_manifest": str(tmp_path / "missing.json")},
        {"proof_body_execution_queue_manifest": str(source_semantic)},
    ) == source_semantic
    assert _proof_body_execution_queue_manifest_from_bridge_manifests(
        None,
        {"proof_body_execution_queue_manifest": str(tmp_path / "missing.json")},
        {},
    ) is None


def test_proof_body_reached_semantic_review_feedback_drives_definition_repair(
    tmp_path: Path,
) -> None:
    learning_rows = [
        {
            "schema_version": 1,
            "learning_task": "exact_source_theorem_proof_body_execution_feedback",
            "trigger": "EXACT_SOURCE_PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED",
            "question_id": "conformal_prediction_coverage",
            "target_theorem_name": "split_conformal_coverage",
            "target_lean_declaration": "split_conformal_coverage",
            "source_work_order_id": "exact_source_work_order:semantic_alignment",
            "execution_result_id": "exact_source_execution_result:proof_body_reached",
            "source_theorem_target_known": True,
            "source_theorem_target_identity_status": "SOURCE_THEOREM_TARGET_KNOWN",
            "source_theorem_target_provenance": {
                "source_theorem_question_id": "conformal_prediction_coverage",
                "target_lean_declaration": "split_conformal_coverage",
            },
            "proof_body_goal_reached": True,
            "proof_body_gate_status": "PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED",
            "semantic_alignment_blockers": [
                "unreviewed synthesized definition semantic risk: "
                "draft finite permutation-invariant joint-law exchangeability still "
                "requires source review and downstream local Lean/AXLE verification",
                "unreviewed synthesized definition semantic risk: "
                "draft sorted finite order statistic uses rank k but still needs "
                "source review for indexing convention, tie behavior, and conformal "
                "quantile rank; the source theorem upper coverage bound is not "
                "eligible for proof-body search until ties are handled by a reviewed "
                "tie policy/no-tie assumption or the theorem is revised",
            ],
            "input_summary": {
                "failure_classification": (
                    "proof_body_reached_semantic_alignment_unreviewed"
                ),
                "target_theorem_name": "split_conformal_coverage",
                "candidate_artifact_path": "runs/candidate.lean",
                "proof_body_goal_reached": True,
                "proof_body_gate_status": (
                    "PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED"
                ),
                "source_theorem_kernel_evidence_eligible": False,
            },
        }
    ]

    work_orders = (
        _runtime_source_theorem_exact_semantic_definition_work_order_rows_from_semantic_alignment_learning_rows(
            learning_rows
        )
    )

    assert {row["placeholder_symbol"] for row in work_orders} == {
        "Exchangeable",
        "orderStat",
    }
    assert all(
        row["source_semantic_alignment_review_required"] is True
        for row in work_orders
    )
    assert all(
        row["source_theorem_target_identity_status"] == "SOURCE_THEOREM_TARGET_KNOWN"
        for row in work_orders
    )
    assert any(
        "tie policy/no-tie assumption" in blocker
        for row in work_orders
        for blocker in row["semantic_alignment_blockers"]
    )

    learning_path = tmp_path / "runtime_learning_rows.jsonl"
    learning_path.write_text(
        "\n".join(
            json.dumps(row)
            for row in _runtime_source_theorem_exact_semantic_definition_learning_rows(
                work_orders
            )
        )
        + "\n",
        encoding="utf-8",
    )
    original_learning_path = tmp_path / "proof_body_feedback.jsonl"
    original_learning_path.write_text(
        "\n".join(json.dumps(row) for row in learning_rows) + "\n",
        encoding="utf-8",
    )
    memory = _load_runtime_learning_memory([original_learning_path, learning_path])
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )
    assert summary["source_theorem_exact_semantic_definition_repair_required"] is True
    assert summary["recommended_source_theorem_integration_action"] == (
        "repair_reviewed_exact_semantic_definitions"
    )
    assert summary["recommended_formalizer_target_mode"] == (
        "source_theorem_exact_semantic_definition_repair"
    )
    assert "EXACT_SOURCE_PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED" in summary[
        "source_theorem_exact_candidate_repair_triggers"
    ]
    assert any(
        "proof_body_gate_status=PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED"
        in diagnostic["diagnostics"]
        for diagnostic in summary["source_theorem_exact_candidate_repair_diagnostics"]
    )
    assert any(
        "upper coverage bound" in blocker
        for diagnostic in summary["source_theorem_exact_candidate_repair_diagnostics"]
        for blocker in diagnostic["semantic_alignment_blockers"]
    )
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet={"packet_id": "theory:test", "formalization_requests": []},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1},
        registered_problem={"problem_class": problem.problem_class},
        theorem_goals=[
            {
                "id": row.id,
                "title": row.title,
                "proof_obligations": list(row.proof_obligations),
            }
            for row in theorem_goals
        ],
        proof_bank_obligation_catalog=catalog,
        proof_bank_runtime_memory_summary=summary,
    )
    assert "source_theorem_exact_semantic_definition_repair" in prompt
    assert "PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED" in prompt
    assert "proof_body_reached_semantic_alignment_unreviewed" in prompt
    assert "proof_body_gate_status" in prompt
    assert "proof_body_goal_reached" in prompt
    assert "upper coverage bound" in prompt
    assert "tie policy/no-tie assumption" in prompt


