def test_runtime_routes_formalizer_source_theorem_gap_target_to_formal_environment_queue() -> None:
    formalization_manifest = {
        "artifact_kind": "RuntimeFormalizationManifest",
        "manifest_id": "formalization_manifest:proposal_gap_route",
        "question": {
            "id": "conformal_prediction_coverage",
            "title": "Split conformal prediction interval coverage",
        },
        "llm_formalizer_proof_engineer_proposal_id": (
            "formalizer_proposal:proposal_gap_route"
        ),
        "proof_bank_runtime_memory_summary": {
            "source_theorem_exact_candidate_environment_gap": False,
        },
    }
    proposal = {
        "artifact_kind": "FormalizerProofEngineerProposalPacket",
        "packet_id": "formalizer_proposal:proposal_gap_route",
        "formal_targets": [
            {
                "id": "split_conformal_helper",
                "lean_statement_sketch": (
                    "theorem split_conformal_helper (p : Prop) (hp : p) : p := hp"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": "false",
                    "target_lean_declaration": "split_conformal_helper",
                    "source_theorem_goal_id": (
                        "split_conformal_finite_sample_coverage"
                    ),
                },
            },
            {
                "id": "split_conformal_source_theorem",
                "informal_source": (
                    "source theorem remains a probability coverage formal gap"
                ),
                "lean_statement_sketch": "",
                "lean_imports": [],
                "semantic_alignment_constraints": [
                    "missing reviewed exchangeability and order statistic primitives",
                    "Mathlib probability imports must be resolved before proof search",
                ],
                "expected_status": "FORMAL_GAP",
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": "true",
                    "target_lean_declaration": "split_conformal_coverage",
                    "source_theorem_goal_id": (
                        "split_conformal_finite_sample_coverage"
                    ),
                },
            },
        ],
    }

    helper_provenance = runtime_module._source_theorem_target_provenance_from_row(
        proposal["formal_targets"][0]
    )
    work_orders = _runtime_source_theorem_formal_environment_work_order_rows(
        [
            {
                "blackboard": {
                    "artifacts": {
                        formalization_manifest["manifest_id"]: formalization_manifest,
                        proposal["packet_id"]: proposal,
                    }
                }
            }
        ]
    )

    assert helper_provenance["source_theorem_target_known"] is False
    assert len(work_orders) == 1
    work_order = work_orders[0]
    assert work_order["artifact_kind"] == "SourceTheoremFormalEnvironmentWorkOrder"
    assert work_order["source_formal_target_id"] == "split_conformal_source_theorem"
    assert work_order["target_theorem_name"] == "split_conformal_coverage"
    assert work_order["target_ids"] == ["split_conformal_finite_sample_coverage"]
    assert work_order["source_theorem_target_known"] is True
    assert work_order["failure_classification"] == (
        "source_theorem_candidate_materialization_required"
    )
    assert work_order["source_theorem_candidate_materialization_required"] is True
    assert work_order["runtime_queue_status"] == (
        "PENDING_SOURCE_THEOREM_FORMAL_ENVIRONMENT_REPAIR_FROM_FORMALIZER_TARGET"
    )
    assert work_order["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"


def test_runtime_routes_materialized_source_theorem_candidate_during_environment_gap(
    tmp_path: Path,
) -> None:
    materialized_candidate_path = tmp_path / "split_conformal_coverage.lean"
    materialized_candidate_path.write_text(
        "theorem split_conformal_coverage "
        "(coverage_claim : Prop) (h : coverage_claim) : coverage_claim := by\n"
        "  exact h\n",
        encoding="utf-8",
    )
    formalization_manifest = {
        "artifact_kind": "RuntimeFormalizationManifest",
        "manifest_id": "formalization_manifest:materialized_candidate_route",
        "question": {
            "id": "conformal_prediction_coverage",
            "title": "Split conformal prediction interval coverage",
        },
        "llm_formalizer_proof_engineer_proposal_id": (
            "formalizer_proposal:materialized_candidate_route"
        ),
        "proof_bank_runtime_memory_summary": {
            "source_theorem_exact_candidate_environment_gap": True,
            "source_theorem_candidate_materialization_required": True,
            "recommended_formalizer_target_mode": (
                "source_theorem_exact_candidate_materialization_required"
            ),
            "source_theorem_candidate_materialization_required_target_ids": [
                "split_conformal_finite_sample_coverage"
            ],
        },
    }
    proposal = {
        "artifact_kind": "FormalizerProofEngineerProposalPacket",
        "packet_id": "formalizer_proposal:materialized_candidate_route",
        "formal_targets": [
            {
                "id": "split_conformal_source_theorem",
                "informal_source": "exact source theorem candidate",
                "lean_statement_sketch": (
                    "theorem split_conformal_coverage "
                    "(coverage_claim : Prop) (h : coverage_claim) : "
                    "coverage_claim := by\n"
                    "  exact h\n"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": True,
                    "target_lean_declaration": "split_conformal_coverage",
                    "source_theorem_goal_id": (
                        "split_conformal_finite_sample_coverage"
                    ),
                },
            }
        ],
    }
    materialization_manifest = {
        "artifact_kind": "RuntimeFormalizerLeanCandidateMaterialization",
        "manifest_id": "formalizer_lean_candidate_materialization:materialized_candidate_route",
        "source_formalizer_packet_id": proposal["packet_id"],
        "candidate_rows": [
            {
                "candidate_id": "split_conformal_source_theorem",
                "candidate_kind": "formal_target_lean_statement_sketch",
                "source_field": "formal_targets",
                "artifact_path": str(materialized_candidate_path),
                "kernel_check_artifact_path": str(materialized_candidate_path),
                "target_lean_declaration": "split_conformal_coverage",
                "target_theorem_name": "split_conformal_coverage",
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "target_theorem_goal_ids": [
                    "split_conformal_finite_sample_coverage"
                ],
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": True,
                    "target_lean_declaration": "split_conformal_coverage",
                    "source_theorem_goal_id": (
                        "split_conformal_finite_sample_coverage"
                    ),
                },
                "local_lean_compiled": False,
            }
        ],
    }

    work_orders = _runtime_source_theorem_formal_environment_work_order_rows(
        [
            {
                "blackboard": {
                    "artifacts": {
                        formalization_manifest["manifest_id"]: formalization_manifest,
                        proposal["packet_id"]: proposal,
                        materialization_manifest["manifest_id"]: (
                            materialization_manifest
                        ),
                    }
                }
            }
        ]
    )

    assert len(work_orders) == 1
    work_order = work_orders[0]
    assert work_order["source_formal_target_id"] == "split_conformal_source_theorem"
    assert work_order["target_theorem_name"] == "split_conformal_coverage"
    assert work_order["target_lean_declaration"] == "split_conformal_coverage"
    assert work_order["target_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert work_order["source_formalizer_expected_status"] == "NEEDS_KERNEL_CHECK"
    assert work_order["source_theorem_candidate_materialization_required"] is False
    assert work_order["candidate_artifact_path"] == str(materialized_candidate_path)
    assert (
        work_order[
            "source_formalizer_lean_candidate_materialization_manifest_id"
        ]
        == materialization_manifest["manifest_id"]
    )
    assert work_order["source_formalizer_lean_candidate_id"] == (
        "split_conformal_source_theorem"
    )
    assert "theorem split_conformal_coverage" in work_order["lean_statement_sketch"]
    assert work_order["runtime_queue_status"] == (
        "PENDING_SOURCE_THEOREM_FORMAL_ENVIRONMENT_REPAIR_FROM_FORMALIZER_TARGET"
    )
    assert work_order["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"


def test_critic_memory_routes_candidate_materialization_blocker_request() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    verified_ids = [str(row["obligation_id"]) for row in catalog]
    materialization_row = {
        "learning_task": "source_theorem_formal_environment_repair_feedback",
        "target_theorem_name": "split_conformal_finite_sample_coverage",
        "target_ids": ["split_conformal_finite_sample_coverage"],
        "target_theorem_goal_ids": ["split_conformal_finite_sample_coverage"],
        "candidate_materialization_required": True,
        "candidate_materialization_statuses": [
            "SIGNATURE_PROBE_BLOCKED_NEEDS_CANDIDATE_ARTIFACT"
        ],
        "candidate_materialization_contract": (
            "Formalizer/ProofEngineer must materialize an exact source-theorem "
            "Lean candidate artifact before signature probes or proof-body "
            "execution can run."
        ),
        "input_summary": {
            "trigger": "SOURCE_THEOREM_FORMAL_ENVIRONMENT_REPAIR_REQUIRED",
            "target_theorem_name": "split_conformal_finite_sample_coverage",
            "target_ids": ["split_conformal_finite_sample_coverage"],
            "candidate_artifact_path": "",
            "failure_classification": "formal_environment_placeholder_primitives",
            "candidate_materialization_required": True,
            "candidate_materialization_statuses": [
                "SIGNATURE_PROBE_BLOCKED_NEEDS_CANDIDATE_ARTIFACT"
            ],
            "missing_formal_symbols": ["coverage_event", "good_rank_event"],
            "signature_probe_rows": [
                {
                    "failure_classification": (
                        "source_theorem_candidate_materialization_required"
                    ),
                    "signature_probe_status": (
                        "SIGNATURE_PROBE_BLOCKED_NEEDS_CANDIDATE_ARTIFACT"
                    ),
                    "candidate_materialization_required": True,
                    "diagnostics": ["candidate_artifact_path missing"],
                }
            ],
        },
    }

    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={
            "runtime_learning_memory": {
                "artifact_kind": "RuntimeLearningMemoryContext",
                "rows": [
                    {"kernel_verified_proof_obligation_ids": verified_ids},
                    materialization_row,
                ],
            }
        },
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=tuple(verified_ids),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["source_theorem_exact_candidate_environment_gap"] is True
    assert summary["source_theorem_candidate_materialization_required"] is True
    assert summary["source_theorem_candidate_materialization_required_target_names"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert summary["source_theorem_candidate_materialization_required_target_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert summary["source_theorem_candidate_materialization_required_statuses"] == [
        "SIGNATURE_PROBE_BLOCKED_NEEDS_CANDIDATE_ARTIFACT"
    ]
    assert summary["source_theorem_candidate_materialization_missing_formal_symbols"] == [
        "coverage_event",
        "good_rank_event",
    ]
    assert "source_theorem_candidate_materialization_required" in summary[
        "source_theorem_exact_candidate_failure_classifications"
    ]

    requests = _critic_formal_blocker_resource_requests(
        formalization_manifest={
            "artifact_kind": "RuntimeFormalizationManifest",
            "manifest_id": "formalization_manifest:candidate_materialization",
            "deterministic_theorem_goals": [
                {"id": "split_conformal_finite_sample_coverage"}
            ],
            "proof_bank_runtime_memory_summary": summary,
        },
        agenda=[],
    )

    materialization_request = next(
        row
        for row in requests
        if row["blocker_kind"]
        == "SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED"
    )
    assert materialization_request["source"] == "proof_bank_runtime_memory_summary"
    assert materialization_request["target_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert "exact source-theorem Lean candidate artifact" in materialization_request[
        "blocker"
    ]
    assert "coverage_event" in materialization_request["blocker"]
    assert materialization_request["proof_evidence_status"] == (
        "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
    )


def test_exact_semantic_repair_blocker_request_preserves_definition_candidate_artifact() -> None:
    feedback = {
        "source_theorem_exact_semantic_definition_repair_required": True,
        "target_names": ["split_conformal_finite_sample_coverage"],
        "diagnostics": [
            {
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "placeholder_symbol": "covered",
                "failure_classification": (
                    "source_theorem_exact_semantic_definition_repair_required"
                ),
                "runtime_queue_status": (
                    "PENDING_EXACT_SEMANTIC_DEFINITION_REVIEW"
                ),
                "proof_body_gate_status": (
                    "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"
                ),
                "definition_only_candidate_artifact_path": (
                    "runs/candidate_artifacts/covered_definition_only.lean"
                ),
                "local_definition_lean_checked": True,
                "local_definition_lean_compiled": True,
                "semantic_definition_typecheck_evidence_status": (
                    "TYPECHECKED_EXACT_SEMANTIC_DEFINITION_CANDIDATE_"
                    "LOCAL_LEAN_COMPILED_REVIEW_REQUIRED"
                ),
                "recommended_next_action": (
                    "review the typechecked definition-only candidate for source "
                    "semantic faithfulness before importing it"
                ),
            }
        ],
    }

    requests = (
        runtime_module._formal_blocker_resource_requests_from_exact_semantic_definition_repair_feedback(
            feedback
        )
    )

    assert len(requests) == 1
    request = requests[0]
    assert request["placeholder_symbol"] == "covered"
    assert request["candidate_artifact_path"] == (
        "runs/candidate_artifacts/covered_definition_only.lean"
    )
    assert request["definition_only_candidate_artifact_path"] == (
        "runs/candidate_artifacts/covered_definition_only.lean"
    )
    assert "candidate_artifact=runs/candidate_artifacts/covered_definition_only.lean" in request[
        "blocker"
    ]
    assert request["proof_evidence_status"] == (
        "FORMAL_BLOCKER_RESOURCE_REQUEST_NOT_PROOF_EVIDENCE"
    )


