def test_critic_agenda_defers_materialization_behind_exact_semantic_gate() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    summary = {
        "source_theorem_candidate_materialization_required": True,
        "source_theorem_candidate_materialization_required_target_ids": [
            "split_conformal_finite_sample_coverage"
        ],
        "source_theorem_candidate_materialization_required_statuses": [
            "EXACT_SOURCE_PROOF_BODY_QUEUE_NOT_READY",
            "SIGNATURE_PROBE_ARTIFACT_PATH_MISSING",
        ],
        "source_theorem_candidate_materialization_contract": (
            "Formalizer/ProofEngineer must materialize an exact source-theorem "
            "Lean candidate artifact with a signature probe and live proof-body "
            "location before exact proof-body execution can run."
        ),
        "source_theorem_exact_semantic_definition_repair_required": True,
        "recommended_formalizer_target_mode": (
            "source_theorem_exact_semantic_definition_repair"
        ),
        "source_theorem_exact_candidate_repair_target_names": [
            "split_conformal_finite_sample_coverage"
        ],
        "source_theorem_exact_candidate_failure_classifications": [
            "typechecked_exact_semantic_definition_candidate_review_required",
            "source_theorem_candidate_materialization_required",
        ],
        "source_theorem_exact_candidate_repair_triggers": [
            "EXACT_SOURCE_SEMANTIC_DEFINITION_TYPECHECKED_SEMANTIC_REVIEW_REQUIRED",
            "EXACT_SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED",
        ],
        "source_theorem_exact_candidate_repair_diagnostics": [
            {
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "placeholder_symbol": "covered",
                "failure_classification": (
                    "typechecked_exact_semantic_definition_candidate_review_required"
                ),
                "runtime_queue_status": (
                    "PENDING_REVIEWED_EXACT_SEMANTIC_DEFINITION_CANDIDATE_REVIEW"
                ),
                "proof_body_gate_status": (
                    "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"
                ),
            }
        ],
    }

    agenda = _critic_next_action_agenda(
        question=question,
        retrieval_manifest={},
        theory_packet={},
        simulation_manifest={"simulation_passed": True},
        algorithm_manifest={},
        formalization_manifest={
            "artifact_kind": "RuntimeFormalizationManifest",
            "manifest_id": "formalization_manifest:semantic_gate_first",
            "counts": {"formal_gap": 1, "kernel_verified": 0, "proved": 0},
            "deterministic_theorem_goals": [
                {"id": "split_conformal_finite_sample_coverage"}
            ],
            "proof_bank_runtime_memory_summary": summary,
        },
    )

    agenda_ids = [row["id"] for row in agenda]
    assert agenda_ids[0] == "formal_gap:source_theorem_exact_semantic_definition_repair"
    assert "formal_gap:source_theorem_candidate_materialization" not in agenda_ids
    exact_agenda = agenda[0]
    assert exact_agenda["deferred_source_theorem_candidate_materialization_required"]
    assert exact_agenda[
        "deferred_source_theorem_candidate_materialization_target_ids"
    ] == ["split_conformal_finite_sample_coverage"]
    assert exact_agenda[
        "deferred_source_theorem_candidate_materialization_statuses"
    ] == [
        "EXACT_SOURCE_PROOF_BODY_QUEUE_NOT_READY",
        "SIGNATURE_PROBE_ARTIFACT_PATH_MISSING",
    ]
    assert "semantic-definition gate" in exact_agenda[
        "deferred_source_theorem_candidate_materialization_reason"
    ]
    assert exact_agenda["proof_body_gate_statuses"] == [
        "SEMANTIC_REVIEW_REQUIRED_BEFORE_PROOF_BODY"
    ]

    stale_semantic_flag_summary = dict(summary)
    stale_semantic_flag_summary[
        "source_theorem_exact_proof_body_gate_open_for_kernel_repair"
    ] = True
    ungated_agenda = _critic_next_action_agenda(
        question=question,
        retrieval_manifest={},
        theory_packet={},
        simulation_manifest={"simulation_passed": True},
        algorithm_manifest={},
        formalization_manifest={
            "artifact_kind": "RuntimeFormalizationManifest",
            "manifest_id": "formalization_manifest:semantic_gate_open",
            "counts": {"formal_gap": 1, "kernel_verified": 0, "proved": 0},
            "deterministic_theorem_goals": [
                {"id": "split_conformal_finite_sample_coverage"}
            ],
            "proof_bank_runtime_memory_summary": stale_semantic_flag_summary,
        },
    )

    assert ungated_agenda[0]["id"] == "formal_gap:source_theorem_candidate_materialization"


def test_candidate_materialization_precedes_verified_adapter_proof_body_retry() -> None:
    memory = runtime_module._runtime_learning_memory_context_from_rows(
        [
            {
                "learning_task": "exact_source_theorem_proof_body_execution_feedback",
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "failure_classification": (
                    "source_theorem_candidate_materialization_required"
                ),
                "runtime_queue_status": (
                    "PENDING_EXACT_SOURCE_THEOREM_CANDIDATE_MATERIALIZATION"
                ),
                "trigger": (
                    "EXACT_SOURCE_THEOREM_CANDIDATE_MATERIALIZATION_REQUIRED"
                ),
                "candidate_materialization_required": True,
                "candidate_materialization_statuses": [
                    "EXACT_SOURCE_PROOF_BODY_QUEUE_NOT_READY",
                    "SIGNATURE_PROBE_ARTIFACT_PATH_MISSING",
                ],
                "candidate_materialization_contract": (
                    "Formalizer/ProofEngineer must materialize an exact "
                    "source-theorem Lean candidate artifact with a signature "
                    "probe before exact proof-body execution can run."
                ),
                "source_theorem_kernel_verified": False,
            },
            {
                "learning_task": "source_theorem_proof_body_adapter_feedback",
                "target_theorem_name": "split_conformal_finite_sample_coverage",
                "target_lean_declaration": (
                    "split_conformal_finite_sample_coverage"
                ),
                "target_ids": ["split_conformal_finite_sample_coverage"],
                "source_theorem_kernel_verified": False,
                "adapter_kernel_verified": True,
                "kernel_verified_source_theorem_proof_body_adapter_ids": [
                    "source_theorem_proof_body_adapter_check:verified"
                ],
                "adapter_candidate_artifact_path": "runs/adapter.lean",
                "adapter_declaration_name": (
                    "split_conformal_finite_sample_coverage_source_to_bridge_adapter"
                ),
                "proof_evidence_status": (
                    "KERNEL_VERIFIED_SOURCE_THEOREM_PROOF_BODY_ADAPTER_PRESENT"
                ),
            },
        ],
        max_rows=10,
    )

    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=[],
        theorem_goals=[{"id": "split_conformal_finite_sample_coverage"}],
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["source_theorem_proof_body_adapter_kernel_verified"] is True
    assert summary["source_theorem_candidate_materialization_required"] is True
    assert summary["source_theorem_exact_proof_body_repair_required"] is False
    assert summary["recommended_source_theorem_integration_action"] == (
        "materialize_exact_source_theorem_candidate"
    )
    assert summary["recommended_formalizer_target_mode"] == (
        "source_theorem_exact_candidate_materialization_required"
    )
    assert summary["source_theorem_candidate_materialization_required_statuses"] == [
        "EXACT_SOURCE_PROOF_BODY_QUEUE_NOT_READY",
        "SIGNATURE_PROBE_ARTIFACT_PATH_MISSING",
    ]
    assert "FORMAL_GAP/helper/premise-only packets do not satisfy" in summary[
        "boundary"
    ]
    assert "target_lean_declaration, signature_probe_artifact_path" in summary[
        "boundary"
    ]


def test_formal_environment_work_order_names_missing_symbols_and_typeclass_blockers() -> None:
    verifier_payload = {
        "rows": [
            {
                "artifact_verification_id": "artifact_verifier:source_env_gap",
                "target_theorem_name": "split_conformal_source_theorem",
                "target_lean_declaration": "split_conformal_source_theorem",
                "source_theorem_target_known": True,
                "source_theorem_target_resolution_id": "target_resolution:split",
                "source_theorem_route_id": "route:split_conformal_source",
                "source_theorem_goal_id": "split_conformal_finite_sample_coverage",
                "target_theorem_goal_ids": [
                    "split_conformal_finite_sample_coverage",
                    "unrelated_broad_runtime_goal",
                ],
                "source_theorem_statement": (
                    "split conformal source coverage theorem"
                ),
                "source_theorem_lean_file": "StatInference/Conformal/SplitCoverage.lean",
                "semantic_alignment_constraints": [
                    "preserve exact source theorem target"
                ],
                "candidate_artifact_path": "/tmp/split_conformal_source_theorem.lean",
                "source_theorem_kernel_verified": False,
                "failure_classification": "formal_environment_symbol_missing",
                "diagnostics": [
                    "failed to synthesize instance of type class\n  HSub ℕ ℝ ENNReal",
                    "Function expected at\n  Exchangeable\nbut this term has type\n  ?m.1\nHint: The identifier `Exchangeable` is unknown in the current environment.",
                    "Function expected at",
                    "  orderStat",
                    "Hint: The identifier `orderStat` is unknown in the current environment.",
                ],
            }
        ]
    }

    work_orders = _source_theorem_formal_environment_work_order_rows_from_artifact_verifier_payload(
        verifier_payload,
        artifact_verifier_manifest="/tmp/artifact_verifier_manifest.json",
    )

    assert len(work_orders) == 1
    work_order = work_orders[0]
    assert work_order["target_lean_declaration"] == "split_conformal_source_theorem"
    assert work_order["target_ids"] == ["split_conformal_finite_sample_coverage"]
    assert work_order["target_theorem_goal_ids"] == [
        "split_conformal_finite_sample_coverage"
    ]
    assert work_order["source_theorem_target_known"] is True
    assert work_order["source_theorem_target_provenance"][
        "source_theorem_target_resolution_id"
    ] == "target_resolution:split"
    assert work_order["source_theorem_target_provenance"][
        "source_theorem_route_id"
    ] == "route:split_conformal_source"
    assert work_order["source_theorem_target_provenance"][
        "source_theorem_statement"
    ] == "split conformal source coverage theorem"
    assert work_order["semantic_alignment_constraints"] == [
        "preserve exact source theorem target"
    ]
    assert work_order["missing_formal_symbols"] == ["Exchangeable", "orderStat"]
    assert work_order["typeclass_blockers"] == ["HSub ℕ ℝ ENNReal"]
    assert any(
        "`Exchangeable`" in task for task in work_order["recommended_repair_tasks"]
    )
    assert any("`orderStat`" in task for task in work_order["recommended_repair_tasks"])
    assert any(
        "`HSub ℕ ℝ ENNReal`" in task
        for task in work_order["recommended_repair_tasks"]
    )
    assert any(
        "runtime-source-theorem-promotion-proofengineer-bridge" in task
        for task in work_order["recommended_repair_tasks"]
    )
    assert work_order["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"


