def test_verified_adapter_goal_shape_feedback_exports_proof_library_work_orders() -> None:
    learning_row = {
        "schema_version": 1,
        "learning_task": "exact_source_theorem_proof_body_execution_feedback",
        "question_id": "conformal_prediction_coverage",
        "target_theorem_name": "split_conformal_coverage",
        "source_theorem_target_known": True,
        "source_theorem_target_provenance": {
            "source_theorem_target_known": True,
            "target_lean_declaration": "split_conformal_coverage",
            "source_theorem_question_id": "conformal_prediction_coverage",
            "source_theorem_goal_id": "split_conformal_finite_sample_coverage",
        },
        "source_work_order_id": (
            "source_theorem_formal_environment_work_order:goal_shape"
        ),
        "execution_queue_id": "exact_source_queue:goal_shape",
        "execution_result_id": "exact_source_result:goal_shape",
        "trigger": "EXACT_SOURCE_PROOF_BODY_VERIFIED_ADAPTER_CONTEXT_INSUFFICIENT",
        "source_theorem_kernel_verified": False,
        "input_summary": {
            "target_theorem_name": "split_conformal_coverage",
            "candidate_artifact_path": "runs/split_conformal_coverage_attempt.lean",
            "source_theorem_kernel_verified": False,
            "failure_classification": (
                "proof_body_verified_adapter_context_insufficient"
            ),
            "proof_body_attempted": True,
            "proof_body_attempt_success": False,
            "proof_body_attempt_summaries": [
                "1:exact split_conformal_coverage_source_to_bridge_adapter:returncode=1:compiled=False:diagnostic_kind=type_mismatch",
            ],
            "proof_body_goal_excerpt": [
                "⊢ 1 - alpha ≤ P.real {ω | s (Fin.last n2) ω ≤ q_hat ω} ∧",
                "    P.real {ω | s (Fin.last n2) ω ≤ q_hat ω} ≤ 1 - alpha + 1 / ↑(n2 + 1)",
            ],
            "exact_goal_shape_obligation_ids": [
                "real_probability_lower_bound_from_ennreal_adapter",
                "conjunctive_source_theorem_split",
                "upper_coverage_bound_component",
                "coverage_event_identification_from_hC",
            ],
            "exact_goal_shape_obligations": [
                "Bridge the ENNReal measure lower-bound adapter to the source theorem's real-valued probability statement.",
                "Assemble lower and upper source theorem proof components.",
                "Prove or supply the upper split-conformal coverage component.",
                "Use the exact coverage-set hypothesis hC to identify the event.",
            ],
        },
        "kernel_verified_source_theorem_ids": [],
        "proof_evidence_status": (
            "EXACT_SOURCE_THEOREM_PROOF_BODY_EXECUTOR_NOT_PROOF_EVIDENCE"
        ),
    }

    work_orders = (
        _runtime_source_theorem_semantic_primitive_work_order_rows_from_learning_rows(
            [learning_row]
        )
    )

    by_obligation = {
        row["exact_goal_shape_obligation_id"]: row for row in work_orders
    }
    assert set(by_obligation) == {
        "real_probability_lower_bound_from_ennreal_adapter",
        "conjunctive_source_theorem_split",
        "upper_coverage_bound_component",
        "coverage_event_identification_from_hC",
    }
    lower = by_obligation["real_probability_lower_bound_from_ennreal_adapter"]
    assert lower["semantic_primitive_gap_kind"] == (
        "source_theorem_exact_goal_shape_obligation"
    )
    assert lower["candidate_registered_obligation_ids"] == [
        "split_conformal_good_rank_coverage_bridge"
    ]
    assert "real-valued probability" in lower["semantic_primitive_gap"]
    upper = by_obligation["upper_coverage_bound_component"]
    assert upper["candidate_registered_obligation_ids"] == [
        "split_conformal_upper_coverage_rank_budget_bridge"
    ]
    assert "upper finite-sample split-conformal coverage" in upper[
        "semantic_primitive_gap"
    ]
    event = by_obligation["coverage_event_identification_from_hC"]
    assert event["candidate_registered_obligation_ids"] == [
        "split_conformal_good_rank_set_inclusion_bridge"
    ]
    conjunction = by_obligation["conjunctive_source_theorem_split"]
    assert conjunction["candidate_registered_obligation_ids"] == [
        "source_theorem_conjunction_from_components"
    ]
    assert "conjunction" in conjunction["semantic_primitive_gap"]
    assert all(
        row["runtime_queue_status"]
        == "PENDING_SOURCE_SEMANTIC_LEAN_PROOF_ATTEMPT"
        for row in work_orders
    )
    assert all(
        row["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"
        for row in work_orders
    )
    assert all(
        row["proof_body_goal_excerpt"]
        == learning_row["input_summary"]["proof_body_goal_excerpt"]
        for row in work_orders
    )


def test_proof_body_reached_semantic_alignment_feedback_exports_semantic_primitive_work_orders() -> None:
    learning_row = {
        "schema_version": 1,
        "learning_task": "exact_source_theorem_proof_body_execution_feedback",
        "target_theorem_name": "split_conformal_coverage",
        "source_theorem_target_known": True,
        "source_theorem_target_provenance": {
            "source_theorem_target_known": True,
            "target_lean_declaration": "split_conformal_coverage",
            "source_theorem_question_id": "conformal_prediction_coverage",
            "source_theorem_goal_id": "split_conformal_finite_sample_coverage",
        },
        "semantic_alignment_constraints": [
            "preserve split conformal marginal coverage semantics",
        ],
        "source_work_order_id": "source_theorem_formal_environment_work_order:seed",
        "execution_queue_id": "exact_source_queue:semantic",
        "execution_result_id": "exact_source_result:semantic",
        "trigger": "EXACT_SOURCE_PROOF_BODY_REACHED_SEMANTIC_REVIEW_REQUIRED",
        "input_summary": {
            "target_theorem_name": "split_conformal_coverage",
            "candidate_artifact_path": "runs/split_conformal_coverage_attempt.lean",
            "source_theorem_kernel_verified": False,
            "failure_classification": (
                "proof_body_reached_semantic_alignment_unreviewed"
            ),
            "semantic_alignment_blockers": [
                "unreviewed synthesized definition semantic risk: draft finite "
                "permutation-invariant joint-law exchangeability still requires "
                "source review",
                "unreviewed synthesized definition semantic risk: draft sorted "
                "finite order statistic uses rank k but still needs source review "
                "for indexing convention, tie behavior, and conformal quantile rank",
            ],
            "proof_body_goal_reached": True,
            "proof_body_attempted": False,
            "proof_body_attempt_success": False,
            "candidate_live_proof_state_request": {
                "proof_body_goal_excerpt": [
                    "⊢ 1 - alpha ≤ P.real {ω | s (Fin.last n2) ω ≤ q_hat ω}"
                ]
            },
        },
        "kernel_verified_source_theorem_ids": [],
        "proof_evidence_status": (
            "EXACT_SOURCE_THEOREM_PROOF_BODY_EXECUTOR_NOT_PROOF_EVIDENCE"
        ),
    }

    work_orders = (
        _runtime_source_theorem_semantic_primitive_work_order_rows_from_learning_rows(
            [learning_row]
        )
    )

    by_symbol = {row["placeholder_symbol"]: row for row in work_orders}
    assert set(by_symbol) == {"Exchangeable", "orderStat"}
    assert by_symbol["Exchangeable"]["semantic_primitive_id"] == (
        "exchangeability_to_uniform_rank_semantics"
    )
    assert by_symbol["orderStat"]["semantic_primitive_id"] == (
        "order_statistic_quantile_semantics"
    )
    assert by_symbol["Exchangeable"]["candidate_registered_obligation_ids"] == [
        "split_conformal_bad_rank_budget_from_uniform_rank_bound"
    ]
    assert by_symbol["orderStat"]["candidate_registered_obligation_ids"] == [
        "split_conformal_good_rank_set_inclusion_bridge"
    ]
    assert by_symbol["Exchangeable"]["failure_classification"] == (
        "proof_body_reached_semantic_alignment_unreviewed"
    )
    assert by_symbol["orderStat"]["semantic_alignment_blockers"]
    assert by_symbol["orderStat"]["semantic_alignment_constraints"] == [
        "preserve split conformal marginal coverage semantics"
    ]
    assert by_symbol["orderStat"]["proof_body_attempted"] is False
    assert by_symbol["orderStat"]["proof_evidence_status"] == (
        "WORK_ORDER_NOT_PROOF_EVIDENCE"
    )
    assert "upstream semantic primitive blocker" in by_symbol["orderStat"][
        "runtime_queue_boundary"
    ]


