def test_runtime_learning_memory_loader_compacts_proof_body_feedback(
    tmp_path: Path,
) -> None:
    learning_path = tmp_path / "oversized_runtime_learning_rows.jsonl"
    long_goal_lines = [
        "goal line " + str(index) + " " + ("x" * 800)
        for index in range(20)
    ]
    learning_row = {
        "schema_version": 1,
        "question_id": "conformal_prediction_coverage",
        "learning_task": "exact_source_theorem_proof_body_execution_feedback",
        "target_theorem_name": "split_conformal_coverage",
        "trigger": "EXACT_SOURCE_PROOF_BODY_LOCAL_LEAN_FAILED",
        "input_summary": {
            "trigger": "EXACT_SOURCE_PROOF_BODY_LOCAL_LEAN_FAILED",
            "target_theorem_name": "split_conformal_coverage",
            "source_theorem_kernel_verified": False,
            "failure_classification": "formal_environment_placeholder_primitives",
            "formal_environment_placeholder_symbols": [
                "Exchangeable",
                "orderStat",
            ],
            "formal_environment_typeclass_blockers": [
                "HSub Nat Real ENNReal",
            ],
            "candidate_live_proof_state_request": {
                "proof_body_goal_excerpt": long_goal_lines,
                "mcp_tool_calls": [
                    {"tool": "lean_goal", "arguments": {"x": "y" * 500}}
                ],
            },
            "proof_body_goal_excerpt": long_goal_lines,
            "diagnostics": [
                "diagnostic " + str(index) + " " + ("z" * 800)
                for index in range(12)
            ],
            "semantic_primitive_checks": [
                {
                    "placeholder_symbol": "Exchangeable",
                    "semantic_primitive_id": (
                        "exchangeability_to_uniform_rank_semantics"
                    ),
                    "target_theorem_name": "split_conformal_coverage",
                    "work_order_id": (
                        "source_theorem_semantic_primitive_work_order:exchangeable"
                    ),
                    "proof_body_goal_excerpt": long_goal_lines,
                }
            ],
        },
    }
    learning_path.write_text(json.dumps(learning_row) + "\n", encoding="utf-8")

    memory = _load_runtime_learning_memory([learning_path])
    compact_row = memory["rows"][0]
    compact_summary = compact_row["input_summary"]

    assert compact_summary["trigger"] == "EXACT_SOURCE_PROOF_BODY_LOCAL_LEAN_FAILED"
    assert compact_summary["target_theorem_name"] == "split_conformal_coverage"
    assert compact_summary["formal_environment_placeholder_symbols"] == [
        "Exchangeable",
        "orderStat",
    ]
    assert "candidate_live_proof_state_request" not in compact_summary
    assert len(compact_summary["proof_body_goal_excerpt"]) == 4
    assert all(len(row) <= 320 for row in compact_summary["proof_body_goal_excerpt"])
    assert len(compact_summary["diagnostics"]) == 4
    assert len(json.dumps(compact_row)) < 5000

    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    summary = _formalizer_proof_bank_runtime_memory_summary(
        context={"runtime_learning_memory": memory},
        proof_bank_obligation_catalog=catalog,
        theorem_goals=theorem_goals,
        memory_kernel_verified_proof_obligation_ids=(),
        memory_prioritized_proof_obligation_ids=(),
    )

    assert summary["source_theorem_exact_candidate_requires_repair"] is True
    assert summary["source_theorem_exact_candidate_environment_gap"] is True
    assert summary["source_theorem_exact_candidate_repair_target_names"] == [
        "split_conformal_coverage"
    ]
    placeholder_symbols = {
        row["placeholder_symbol"]
        for row in summary["source_theorem_exact_candidate_placeholder_resolution_plan"]
    }
    assert {"Exchangeable", "orderStat"} <= placeholder_symbols


