def test_formalizer_validator_rejects_adapter_placeholder_syntax_and_full_target_statement() -> None:
    packet = {
        "formal_targets": [
            {
                "id": "target:bad-adapter",
                "informal_source": "adapter proposal",
                "lean_statement_sketch": (
                    "theorem split_conformal_coverage_source_to_bridge_adapter "
                    "(hExch : /* exchangeability hypothesis placeholder */) : "
                    "True := by\n"
                    "  exact True.intro"
                ),
                "lean_imports": ["Mathlib"],
                "semantic_alignment_constraints": ["derive bridge premise"],
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": True,
                    "target_lean_declaration": (
                        "theorem split_conformal_coverage : True := by trivial"
                    ),
                    "source_theorem_goal_id": (
                        "split_conformal_finite_sample_coverage"
                    ),
                },
                "expected_status": "NEEDS_KERNEL_CHECK",
            }
        ],
        "lemma_dependency_plan": [
            {"from": "source hypotheses", "to": "bridge premise", "role": "adapter", "risk": "semantic gap"}
        ],
        "retrieval_queries": [
            {"query": "split conformal coverage bridge", "target_library": "StatInference", "purpose": "adapter"}
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "tactic_or_certificate_hints": ["derive bridge premise"],
            "kernel_check_plan": ["run local Lean"],
            "known_blockers": ["semantic adapter"],
        },
        "proof_bank_obligation_requests": [],
        "gap_taxonomy": [
            {"gap": "semantic adapter missing", "kind": "semantic_alignment", "next_owner": "ProofEngineer"}
        ],
        "critic_findings": [
            {"critic": "validator", "finding": "adapter needs local Lean", "reroute_if_confirmed": "ProofEngineer"}
        ],
        "next_actions": [
            {"owner_agent": "ProofEngineer", "action": "replace placeholder binder", "acceptance_gate": "local Lean"}
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }

    errors = validate_formalizer_packet(packet)

    assert any("target_lean_declaration must be a Lean declaration identifier" in error for error in errors)
    assert any("contains C-style placeholder comment syntax" in error for error in errors)


