def test_formalizer_validator_rejects_vacuous_true_source_to_bridge_candidate() -> None:
    packet = {
        "formal_targets": [
            {
                "id": "split_conformal_hGoodCovered_repair",
                "informal_source": "derive hGoodCovered from source hypotheses",
                "lean_statement_sketch": (
                    "theorem split_conformal_hGoodCovered_repair "
                    "(covered : Set Nat) : covered ⊆ covered := by\n"
                    "  intro x hx\n"
                    "  exact hx"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
            }
        ],
        "lemma_dependency_plan": [
            {
                "from": "exact source hypotheses",
                "to": "hGoodCovered",
                "role": "source-to-bridge premise derivation",
                "risk": "semantic alignment",
            }
        ],
        "retrieval_queries": [
            {
                "query": "split conformal good rank containment",
                "target_library": "StatInference",
                "purpose": "premise derivation",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "kernel_check_plan": ["run local Lean on premise candidate"],
            "known_blockers": [],
        },
        "proof_bank_obligation_requests": [],
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_name": "hGoodCovered",
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "premise_derivation_candidate_lean_source": (
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    ": True := by\n"
                    "  trivial\n"
                ),
            }
        ],
        "gap_taxonomy": [
            {"gap": "premise derivation still unproved", "kind": "semantic_alignment"}
        ],
        "critic_findings": [
            {"critic": "validator", "finding": "vacuous candidate must be rejected"}
        ],
        "next_actions": [
            {"owner_agent": "ProofEngineer", "action": "replace vacuous candidate"}
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }

    errors = validate_formalizer_packet(packet)

    assert any("vacuous True" in error for error in errors)


def test_formalizer_validator_rejects_missing_source_to_bridge_anchor_references() -> None:
    packet = {
        "formal_targets": [
            {
                "id": "split_conformal_hGoodCovered_repair",
                "informal_source": "derive hGoodCovered from source hypotheses",
                "lean_statement_sketch": (
                    "theorem split_conformal_hGoodCovered_repair "
                    "(covered : Set Nat) : covered ⊆ covered := by\n"
                    "  intro x hx\n"
                    "  exact hx"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
            }
        ],
        "lemma_dependency_plan": [
            {
                "from": "exact source hypotheses",
                "to": "hGoodCovered",
                "role": "source-to-bridge premise derivation",
                "risk": "semantic alignment",
            }
        ],
        "retrieval_queries": [
            {
                "query": "split conformal good rank containment hq hC",
                "target_library": "StatInference",
                "purpose": "premise derivation",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "kernel_check_plan": ["run local Lean on premise candidate"],
            "known_blockers": [],
        },
        "proof_bank_obligation_requests": [],
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_name": "hGoodCovered",
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "required_semantic_anchor_reference_names": ["hq", "hC"],
                "premise_derivation_candidate_lean_source": (
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    "(covered : Set Nat) : covered ⊆ covered := by\n"
                    "  -- hq and hC are intentionally only mentioned in a comment\n"
                    "  intro x hx\n"
                    "  exact hx\n"
                ),
            }
        ],
        "gap_taxonomy": [
            {"gap": "premise derivation still unproved", "kind": "semantic_alignment"}
        ],
        "critic_findings": [
            {
                "critic": "validator",
                "finding": "candidate must reference required source anchors",
            }
        ],
        "next_actions": [
            {"owner_agent": "ProofEngineer", "action": "replace anchor-free candidate"}
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }

    errors = validate_formalizer_packet(packet)
    directives = runtime_module._formalizer_packet_validation_repair_directives(errors)

    assert any("missing required semantic anchor references" in error for error in errors)
    assert any("hq" in error and "hC" in error for error in errors)
    assert any(
        "referencing every missing required semantic anchor" in directive
        for directive in directives
    )


