def test_formalizer_validator_rejects_phantom_source_to_bridge_next_action() -> None:
    packet = {
        "formal_targets": [
            {
                "id": "split_conformal_finite_sample_coverage_source_theorem",
                "formal_target_role": (
                    FORMAL_TARGET_ROLE_SOURCE_THEOREM_FORMAL_GAP
                ),
                "informal_source": "source theorem remains a formal gap",
                "lean_statement_sketch": "",
                "expected_status": "FORMAL_GAP",
                "source_theorem_target_provenance": {
                    "source_theorem_target_known": True,
                    "target_lean_declaration": "split_conformal_finite_sample_coverage",
                },
            }
        ],
        "lemma_dependency_plan": [
            {
                "from": "verified bridge lemmas",
                "to": "source theorem coverage conclusion",
                "role": "theorem-level closure",
                "risk": "missing source-to-bridge premise derivation",
            }
        ],
        "retrieval_queries": [
            {
                "query": "split conformal source-to-bridge premise derivation",
                "target_library": "StatInference",
                "purpose": "find exact premise derivation",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "kernel_check_plan": ["check emitted source-to-bridge candidates only"],
            "known_blockers": ["source theorem still unproved"],
        },
        "proof_bank_obligation_requests": [],
        "source_to_bridge_premise_derivation_candidates": [],
        "gap_taxonomy": [
            {
                "gap": "source theorem remains unproved",
                "kind": "proof_search",
                "next_owner": "ProofEngineer",
            }
        ],
        "critic_findings": [
            {
                "critic": "validator",
                "finding": "next action must not reference missing candidates",
            }
        ],
        "next_actions": [
            {
                "owner_agent": "AgentRuntime/AXLE",
                "action": (
                    "Run local Lean kernel check on "
                    "source_to_bridge_premise_derivation_candidates entry "
                    "conformal_coverage_prob_lower_bound_from_rank_bridge"
                ),
                "acceptance_gate": "Local Lean exit status 0",
            }
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }

    errors = validate_formalizer_packet(packet)
    directives = runtime_module._formalizer_packet_validation_repair_directives(errors)

    assert any("packet contains no source_to_bridge" in error for error in errors)
    assert any("phantom source-to-bridge" in directive for directive in directives)


def test_formalizer_autofills_source_to_bridge_metadata_from_runtime_memory(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    skeleton_path = tmp_path / "hGoodCovered_skeleton.lean"
    skeleton_path.write_text(
        "\n".join(
            [
                "import Mathlib",
                "",
                "namespace Test",
                "",
                "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation",
                "    (hq hC : Prop) : hq ∧ hC := by",
                "  -- ProofEngineer must replace this generated skeleton body.",
                "  fail_if_success trivial",
                "",
                "end Test",
                "",
            ]
        ),
        encoding="utf-8",
    )
    response = {
        "formal_targets": [
            {
                "id": "split_conformal_hGoodCovered_repair",
                "informal_source": "derive hGoodCovered from source hypotheses",
                "lean_statement_sketch": (
                    "theorem split_conformal_hGoodCovered_repair "
                    "(hq hC : Prop) : hq ∧ hC := by\n"
                    "  exact And.intro hq hC"
                ),
                "expected_status": "NEEDS_KERNEL_CHECK",
            }
        ],
        "lemma_dependency_plan": [
            {
                "from": "exact source hypotheses",
                "to": "hGoodCovered",
                "role": "source-to-bridge premise derivation",
                "risk": "semantic alignment",
            }
        ],
        "retrieval_queries": [
            {
                "query": "split conformal source-to-bridge premise derivation",
                "target_library": "StatInference",
                "purpose": "premise derivation",
            }
        ],
        "proof_search_plan": {
            "preferred_tools": ["local Lean"],
            "kernel_check_plan": ["run local Lean on premise candidate"],
            "known_blockers": [],
        },
        "proof_bank_obligation_requests": [],
        "source_to_bridge_premise_derivation_candidates": [
            {
                "premise_name": "hGoodCovered",
                "target_theorem_name": "split_conformal_coverage",
                "target_lean_declaration": "split_conformal_coverage",
                "premise_derivation_candidate_lean_source": (
                    "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation "
                    "(hq hC : Prop) : hq ∧ hC := by\n"
                    "  exact And.intro hq hC\n"
                ),
            }
        ],
        "gap_taxonomy": [
            {"gap": "premise derivation still unproved", "kind": "semantic_alignment"}
        ],
        "critic_findings": [
            {
                "critic": "validator",
                "finding": "candidate needs runtime request metadata",
            }
        ],
        "next_actions": [
            {"owner_agent": "ProofEngineer", "action": "run local Lean after validation"}
        ],
        "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
        "kernel_verified": False,
        "full_frontier_theorem_proved": False,
    }
    memory_summary = {
        "recommended_formalizer_target_mode": (
            "source_to_bridge_premise_derivation_required"
        ),
        "source_to_bridge_premise_derivation_required": True,
        "source_to_bridge_premise_derivation_diagnostics": [
            {
                "premise_name": "hGoodCovered",
                "source_to_bridge_premise_derivation_candidate_request_id": (
                    "source_to_bridge_premise_derivation_candidate_request:hGoodCovered"
                ),
                "source_to_bridge_premise_derivation_candidate_request": {
                    "candidate_request_id": (
                        "source_to_bridge_premise_derivation_candidate_request:hGoodCovered"
                    ),
                    "premise_name": "hGoodCovered",
                    "premise_target_type": "{ω | rank ω ∈ BadRanks}ᶜ ⊆ covered",
                    "premise_candidate_declaration_name": (
                        "split_conformal_coverage_hGoodCovered_source_to_bridge_derivation"
                    ),
                    "premise_candidate_artifact_path": str(skeleton_path),
                    "required_semantic_anchor_reference_names": ["hq", "hC"],
                    "adapter_object_names_requiring_source_instantiation": [
                        "covered",
                        "rank",
                        "BadRanks",
                    ],
                },
            }
        ],
    }
    prompt = build_formalizer_prompt(
        question=question,
        theory_packet={"packet_id": "theory:metadata-autofill"},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1},
        registered_problem={"problem_class": "conformal_prediction"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary=memory_summary,
    )

    assert str(skeleton_path) in prompt
    assert "premise_derivation_candidate_skeleton_lean_source_excerpt" in prompt
    assert (
        "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation"
        in prompt
    )
    assert "reuse that generated theorem name/header" in prompt

    formalizer = LLMFormalizerProofEngineerAgent(
        provider=StaticArchitectLLMProvider(response),
        config=FormalizerConfig(provider_name="static", model="static-formalizer"),
    )

    packet = formalizer.propose(
        question=question,
        theory_packet={"packet_id": "theory:metadata-autofill"},
        simulation_manifest={"manifest_id": "simulation:test", "simulation_passed": True},
        algorithm_manifest={"manifest_id": "algorithm:test", "n_executed": 1},
        registered_problem={"problem_class": "conformal_prediction"},
        theorem_goals=[],
        proof_bank_obligation_catalog=[],
        proof_bank_runtime_memory_summary=memory_summary,
    )

    candidate = packet["source_to_bridge_premise_derivation_candidates"][0]
    assert candidate["source_binding_metadata_autofilled_from_runtime_memory"] is True
    assert candidate[
        "source_to_bridge_premise_derivation_candidate_request_id"
    ] == "source_to_bridge_premise_derivation_candidate_request:hGoodCovered"
    assert candidate["required_semantic_anchor_reference_names"] == ["hq", "hC"]
    assert candidate["adapter_object_names_requiring_source_instantiation"] == [
        "covered",
        "rank",
        "BadRanks",
    ]
    assert candidate["premise_candidate_artifact_path"] == str(skeleton_path)
    assert (
        "theorem split_conformal_coverage_hGoodCovered_source_to_bridge_derivation"
        in candidate["premise_derivation_candidate_skeleton_lean_source_excerpt"]
    )
    assert validate_formalizer_packet(packet) == []


