def test_formalization_runtime_suppresses_llm_requests_already_kernel_verified_in_memory() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[0]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }

    class StaticFormalizer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            packet = dict(_formalizer_sample_response())
            packet.update(
                {
                    "schema_version": 1,
                    "artifact_kind": "FormalizerProofEngineerProposalPacket",
                    "packet_id": "formalizer_proposal:memory_suppression",
                    "source_agent": "StaticFormalizer",
                    "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                    "kernel_verified": False,
                    "full_frontier_theorem_proved": False,
                }
            )
            return packet

    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=StaticFormalizer(),
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=1,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {"manifest_id": "algorithm_sandbox_manifest:test"},
        },
    )
    task = AgentTask(
        task_id="task:formalization_memory_suppression",
        owner_subsystem="FormalizationEvaluator",
        objective="test proof-obligation memory suppression",
        inputs={
            "question": question_payload,
            "architect_context": {
                "runtime_learning_memory": {
                    "artifact_kind": "RuntimeLearningMemoryContext",
                    "rows": [
                        {
                            "kernel_verified_proof_obligation_ids": ["variance_nonneg"],
                            "recommended_proof_obligation_ids": ["event_indicator_expectation"],
                        }
                    ],
                }
            },
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
        },
    )

    result = subsystem.run(task, blackboard)
    manifest = next(
        row
        for key, row in result.produced_artifacts.items()
        if key.startswith("formalization_manifest:")
    )
    control = manifest["proof_obligation_control"]

    assert control["memory_kernel_verified_proof_obligation_ids"] == ["variance_nonneg"]
    assert control["memory_prioritized_proof_obligation_ids"] == ["event_indicator_expectation"]
    assert control["llm_requested_proof_obligation_ids"] == ["variance_nonneg"]
    assert control["llm_prioritized_proof_obligation_ids"] == []
    assert control["llm_suppressed_kernel_verified_proof_obligation_ids"] == ["variance_nonneg"]
    assert control["excluded_proof_obligation_ids"] == ["variance_nonneg"]
    assert control["excluded_candidate_proof_obligation_ids"] == ["variance_nonneg"]
    assert control["prioritized_proof_obligation_ids"] == ["event_indicator_expectation"]
    assert "variance_nonneg" not in control["eligible_proof_obligation_ids_before_limit"]
    assert control["selected_priority_proof_obligation_ids"] == ["event_indicator_expectation"]
    assert "variance_nonneg" not in control["selected_proof_obligation_ids"]
    assert "variance_nonneg" not in control["deferred_proof_obligation_ids_due_to_max"]


def test_formalization_runtime_exports_theorem_reduction_closure_work_order() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    verified_ids = [str(row["obligation_id"]) for row in catalog]

    class StaticClosureFormalizer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            packet = dict(_formalizer_sample_response())
            packet.update(
                {
                    "schema_version": 1,
                    "artifact_kind": "FormalizerProofEngineerProposalPacket",
                    "packet_id": "formalizer_proposal:closure",
                    "source_agent": "StaticClosureFormalizer",
                    "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                    "kernel_verified": False,
                    "full_frontier_theorem_proved": False,
                    "formal_targets": [
                            {
                                "id": "split_conformal_finite_sample_coverage_reduction_closure",
                                "informal_source": "connect verified conformal bridge obligations to the frontier theorem",
                                "target_lean_declaration": (
                                    "split_conformal_finite_sample_coverage_reduction_closure"
                                ),
                                "lean_statement_sketch": (
                                    "theorem split_conformal_finite_sample_coverage_reduction_closure : "
                                    "True := by\n  trivial\n"
                                ),
                            "semantic_alignment_constraints": ["marginal coverage only"],
                            "expected_status": "OPEN",
                        }
                    ],
                    "proof_bank_obligation_requests": [],
                    "gap_taxonomy": [
                        {
                            "gap": "theorem-level reduction closure still needs Lean proof",
                            "kind": "proof_search",
                            "next_owner": "ProofEngineer/AgentRuntime",
                        }
                    ],
                }
            )
            return packet

    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=StaticClosureFormalizer(),
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=1,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {"manifest_id": "algorithm_sandbox_manifest:test"},
        },
    )
    task = AgentTask(
        task_id="task:formalization_theorem_closure_work_order",
        owner_subsystem="FormalizationEvaluator",
        objective="test theorem closure work-order export",
        inputs={
            "question": question_payload,
            "architect_context": {
                "research_problem_authority_mode": "legacy_baseline",
                "runtime_requested_evidence_contract": {
                    "evaluation_mode": "capability_eval",
                    "capability_eval_requires_formalizer_lean_candidate": True,
                },
                "runtime_learning_memory": {
                    "artifact_kind": "RuntimeLearningMemoryContext",
                    "rows": [
                        {
                            "kernel_verified_proof_obligation_ids": verified_ids,
                            "recommended_proof_obligation_ids": verified_ids,
                        }
                    ],
                },
                "environment_feedback": {
                    "high_priority_agenda": [
                        {
                            "id": "formal_gap:theorem_reduction_closure",
                            "owner_subsystem": "Formalizer/LeanProver",
                        }
                    ]
                },
            },
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
        },
    )

    result = subsystem.run(task, blackboard)
    manifest = next(
        row
        for key, row in result.produced_artifacts.items()
        if key.startswith("formalization_manifest:")
    )
    control = manifest["proof_obligation_control"]
    work_orders = manifest["theorem_reduction_closure_work_orders"]

    assert control["proof_bank_bridge_catalog_exhausted_by_memory"] is True
    assert control["theorem_reduction_closure_required"] is True
    assert control["n_selected_proof_obligations"] == 0
    assert manifest["counts"]["theorem_reduction_closure_work_orders"] == 1
    assert work_orders[0]["artifact_kind"] == "TheoremReductionClosureWorkOrder"
    assert work_orders[0]["proof_mode"] == "theorem_level_reduction_closure"
    assert work_orders[0]["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"
    assert work_orders[0]["candidate_bytes_preserved"] is True
    assert work_orders[0]["candidate_generation_required"] is False
    assert work_orders[0]["candidate_source_hash"] == runtime_module.stable_hash(
        work_orders[0]["lean_statement_sketch"]
    )
    assert work_orders[0]["target_theorem_goal_ids"] == ["split_conformal_finite_sample_coverage"]
    assert set(work_orders[0]["verified_bridge_obligation_ids"]) == set(verified_ids)
    queue_rows = _runtime_theorem_reduction_closure_work_order_rows(
        [{"blackboard": {"artifacts": result.produced_artifacts}}]
    )
    assert len(queue_rows) == 1
    assert queue_rows[0]["work_order_id"] == work_orders[0]["work_order_id"]
    assert queue_rows[0]["source_formalization_manifest_id"] == manifest["manifest_id"]
    assert queue_rows[0]["question_id"] == "conformal_prediction_coverage"
    assert queue_rows[0]["runtime_queue_status"] == "PENDING_LEAN_PROOF_ATTEMPT"
    assert "not proof evidence" in queue_rows[0]["runtime_queue_boundary"]


def test_formalization_runtime_uses_deterministic_theorem_closure_when_memory_exhausted() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    verified_ids = [str(row["obligation_id"]) for row in catalog]

    class ExplodingFormalizer:
        def propose(self, **_kwargs: object) -> dict[str, object]:
            raise AssertionError("Formalizer should not be called after proof-bank memory is exhausted")

    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=ExplodingFormalizer(),
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=1,
        runtime_config=ResearchAgentRuntimeConfig(
            theorem_closure_proofengineer_bridge=True,
            theorem_closure_proofengineer_local_lean=False,
        ),
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {"manifest_id": "algorithm_sandbox_manifest:test"},
        },
    )
    task = AgentTask(
        task_id="task:formalization_deterministic_theorem_closure",
        owner_subsystem="FormalizationEvaluator",
        objective="test deterministic theorem closure when proof-bank memory is exhausted",
        inputs={
            "question": question_payload,
            "architect_context": {
                "runtime_learning_memory": {
                    "artifact_kind": "RuntimeLearningMemoryContext",
                    "rows": [
                        {
                            "kernel_verified_proof_obligation_ids": verified_ids,
                            "recommended_proof_obligation_ids": verified_ids,
                        }
                    ],
                },
            },
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
        },
    )

    result = subsystem.run(task, blackboard)
    manifest = next(
        row
        for key, row in result.produced_artifacts.items()
        if key.startswith("formalization_manifest:")
    )
    proposal_id = manifest["llm_formalizer_proof_engineer_proposal_id"]
    proposal = result.produced_artifacts[proposal_id]
    control = manifest["proof_obligation_control"]
    work_orders = manifest["theorem_reduction_closure_work_orders"]
    proposal_evidence = next(
        row
        for row in result.evidence_entries
        if row.artifact_id == proposal_id
    )

    assert proposal["source_agent"] == "DeterministicTheoremClosureWorkOrderSeed"
    assert proposal["provider"] == "deterministic"
    assert proposal["proof_evidence_status"] == (
        "DETERMINISTIC_THEOREM_CLOSURE_PACKET_NOT_PROOF_EVIDENCE"
    )
    assert manifest["formalizer_proposal_source"] == (
        "deterministic_theorem_closure_work_order_seed"
    )
    assert manifest["llm_formalizer_proof_engineer_proposal_observed"] is False
    assert manifest["deterministic_formalizer_work_order_seed_used"] is True
    assert manifest["formalizer_agentic_capability_evidence_status"] == (
        "DETERMINISTIC_WORK_ORDER_SEED_NOT_AGENTIC_CAPABILITY"
    )
    assert proposal["proof_bank_obligation_requests"] == []
    target = proposal["formal_targets"][0]
    assert target["expected_status"] == "FORMAL_GAP"
    assert target["lean_statement_sketch"] == ""
    assert target["target_lean_declaration"] == ""
    assert target["candidate_generation_required"] is True
    assert target["candidate_generation_request"]["request_kind"] == (
        "llm_theorem_reduction_closure_candidate"
    )
    assert "Python runtime must not generate" in target[
        "candidate_generation_request"
    ]["forbidden_runtime_substitution"]
    assert proposal["proof_search_plan"]["tactic_or_certificate_hints"] == []
    assert control["proof_bank_bridge_catalog_exhausted_by_memory"] is True
    assert control["theorem_reduction_closure_required"] is True
    assert control["n_selected_proof_obligations"] == 0
    assert control["selected_proof_obligation_ids"] == []
    assert control["llm_requested_proof_obligation_ids"] == []
    assert work_orders and len(work_orders) == 1
    assert work_orders[0]["proof_evidence_status"] == "WORK_ORDER_NOT_PROOF_EVIDENCE"
    assert work_orders[0]["lean_statement_sketch"] == ""
    assert work_orders[0]["candidate_source_hash"] == ""
    assert work_orders[0]["candidate_generation_required"] is True
    assert work_orders[0]["candidate_generation_request"]["request_kind"] == (
        "llm_theorem_reduction_closure_candidate"
    )
    assert work_orders[0]["target_theorem_goal_ids"] == ["split_conformal_finite_sample_coverage"]
    assert set(work_orders[0]["verified_bridge_obligation_ids"]) == set(verified_ids)
    typed_work_order = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.THEOREM_REDUCTION_CLOSURE_RUNTIME_WORK_ORDER_KIND
    )
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == (
        runtime_module.THEOREM_REDUCTION_CLOSURE_PROOFENGINEER_SUBSYSTEM
    )
    assert typed_work_order["source_formalization_manifest_id"] == (
        manifest["manifest_id"]
    )
    assert typed_work_order["execution_policy_fingerprint"] == (
        runtime_module.stable_hash(typed_work_order["execution_policy"])
    )
    assert proposal_evidence.evidence_type == "deterministic_theorem_closure_work_order_seed"
    assert proposal_evidence.status == "WORK_ORDER_SEED_RECORDED_NOT_PROOF_EVIDENCE"


def _theorem_closure_worker_fixture(
    tmp_path: Path,
    *,
    lean_source: str,
    local_lean: bool,
) -> tuple[OpenResearchQuestion, BlackboardState, AgentTask, dict[str, object]]:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    target_declaration = "closure_candidate" if lean_source.strip() else ""
    inner_work_order = {
        "schema_version": 1,
        "artifact_kind": "TheoremReductionClosureWorkOrder",
        "work_order_id": "theorem_reduction_closure_work_order:typed_worker",
        "source_formalizer_packet_id": "formalizer_proposal:typed_worker",
        "source_formal_target_id": "frontier_target_reduction_closure",
        "target_theorem_goal_ids": ["frontier_target"],
        "verified_bridge_obligation_ids": ["bridge_obligation"],
        "remaining_unverified_proof_bank_obligation_ids": [],
        "target_lean_declaration": target_declaration,
        "lean_statement_sketch": lean_source,
        "candidate_source_hash": (
            runtime_module.stable_hash(lean_source) if lean_source else ""
        ),
        "candidate_bytes_preserved": True,
        "candidate_generation_required": not bool(lean_source.strip()),
        "candidate_generation_request": {
            "request_kind": "llm_theorem_reduction_closure_candidate",
            "target_theorem_goal_ids": ["frontier_target"],
        },
        "semantic_alignment_constraints": [
            "preserve the source theorem target and assumptions"
        ],
        "proof_mode": "theorem_level_reduction_closure",
        "proof_evidence_status": "WORK_ORDER_NOT_PROOF_EVIDENCE",
        "proof_evidence_boundary": runtime_module.KERNEL_PROOF_BOUNDARY,
    }
    formalization_manifest = {
        "schema_version": 1,
        "artifact_kind": "RuntimeFormalizationManifest",
        "manifest_id": "formalization_manifest:typed_closure_worker",
        "question": runtime_module._question_to_payload(question),
        "theorem_reduction_closure_work_orders": [inner_work_order],
    }
    source_task = AgentTask(
        task_id="formalize:typed_closure_worker",
        owner_subsystem="FormalizationEvaluator",
        objective="emit a theorem-reduction closure work order",
        inputs={
            "question": runtime_module._question_to_payload(question),
            "architect_context": {},
        },
    )
    critic_task = AgentTask(
        task_id="critic:typed_closure_worker",
        owner_subsystem="CriticEvaluator",
        objective="review theorem-reduction closure evidence",
        inputs={
            "question": runtime_module._question_to_payload(question),
            "formalization_manifest_id": formalization_manifest["manifest_id"],
            "architect_context": {},
        },
    )
    runtime_config = ResearchAgentRuntimeConfig(
        theorem_closure_proofengineer_bridge=True,
        theorem_closure_proofengineer_local_lean=local_lean,
        theorem_closure_proofengineer_lean_project=str(tmp_path / "LeanProject"),
    )
    work_order = runtime_module._runtime_theorem_reduction_closure_work_order(
        source_task=source_task,
        question=question,
        architect_context={},
        formalization_manifest=formalization_manifest,
        return_task=critic_task,
        runtime_config=runtime_config,
    )
    dispatch_task = runtime_module._runtime_theorem_reduction_closure_dispatch_task(
        question=question,
        architect_context={},
        work_order=work_order,
    )
    blackboard = BlackboardState(
        project_id="typed-theorem-closure-worker",
        artifacts={
            formalization_manifest["manifest_id"]: formalization_manifest,
            work_order["work_order_id"]: work_order,
        },
    )
    return question, blackboard, dispatch_task, work_order


def test_formalization_dispatches_hash_bound_exact_source_candidate_to_typed_child(
    tmp_path: Path,
) -> None:
    question = load_open_research_questions(
        Path("examples/research_questions.json")
    )[0]
    response = _formalizer_sample_response()
    response["formal_targets"] = [
        {
            "id": "exact_source_target",
            "informal_source": "exact source theorem fixture",
            "lean_statement_sketch": (
                "theorem exact_source_target (p : Prop) (hp : p) : p := by\n"
                "  exact hp\n"
            ),
            "semantic_alignment_constraints": [
                "preserve the exact source theorem proposition"
            ],
            "source_theorem_target_provenance": {
                "source_theorem_target_known": True,
                "source_theorem_question_id": question.id,
                "target_lean_declaration": "exact_source_target",
                "target_ids": ["exact_source_target"],
            },
            "source_theorem_formal_environment_repair_required": True,
            "expected_status": "OPEN",
        }
    ]
    formalizer = LLMFormalizerProofEngineerAgent(
        provider=StaticArchitectLLMProvider(response),
        config=FormalizerConfig(
            provider_name="static",
            model="static-formalizer-model",
        ),
    )
    config = ResearchAgentRuntimeConfig(
        source_theorem_formal_environment_proofengineer_bridge=True,
        source_theorem_formal_environment_proofengineer_execute_proof_body=True,
        source_theorem_formal_environment_proofengineer_signature_probes=False,
        source_theorem_formal_environment_proofengineer_proof_body_local_lean=False,
    )
    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=formalizer,
        proof_verifier=MockProofVerifier(),
        lean_candidate_root=tmp_path / "candidates",
        runtime_config=config,
    )
    theory_packet = _runtime_sample_response()
    theory_packet_id = str(theory_packet["packet_id"])
    blackboard = BlackboardState(
        project_id="typed-exact-source-dispatch",
        artifacts={
            theory_packet_id: theory_packet,
            "simulation_manifest:typed_exact": {
                "manifest_id": "simulation_manifest:typed_exact",
                "simulation_passed": True,
            },
            "algorithm_sandbox_manifest:typed_exact": {
                "manifest_id": "algorithm_sandbox_manifest:typed_exact",
                "sandbox_passed": True,
            },
        },
    )
    task = AgentTask(
        task_id="formalize:typed_exact_source_dispatch",
        owner_subsystem="FormalizationEvaluator",
        objective="Dispatch an exact source theorem compiler task",
        inputs={
            "question": runtime_module._question_to_payload(question),
            "theory_packet_id": theory_packet_id,
            "simulation_manifest_id": "simulation_manifest:typed_exact",
            "algorithm_sandbox_manifest_id": (
                "algorithm_sandbox_manifest:typed_exact"
            ),
            "architect_context": {},
        },
    )

    result = subsystem.run(task, blackboard)

    assert result.next_task is not None
    assert result.next_task.owner_subsystem == (
        runtime_module.EXACT_SOURCE_THEOREM_PROOF_BODY_SUBSYSTEM
    )
    manifest = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
    )
    rows = manifest["runtime_exact_source_theorem_proof_body_rows"]
    assert len(rows) == 1
    assert rows[0]["target_lean_declaration"] == "exact_source_target"
    assert rows[0]["target_lean_declaration_source"] == (
        "formalizer_structured_source_theorem_target_provenance"
    )
    assert rows[0]["candidate_source_hash"]
    work_order = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.EXACT_SOURCE_THEOREM_PROOF_BODY_RUNTIME_WORK_ORDER_KIND
    )
    assert work_order["source_formalization_manifest_hash"] == (
        runtime_module.stable_hash(manifest)
    )
    assert work_order["source_candidate_artifact_bindings"][0]["content_hash"] == (
        rows[0]["candidate_source_hash"]
    )
    assert work_order["execution_policy"]["candidate_source_policy"].endswith(
        "Lean grammar or tactics."
    )


def test_formalization_dispatches_exact_semantic_loop_to_typed_child(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    question = load_open_research_questions(
        Path("examples/research_questions.json")
    )[0]
    response = _formalizer_sample_response()
    formalizer = LLMFormalizerProofEngineerAgent(
        provider=StaticArchitectLLMProvider(response),
        config=FormalizerConfig(
            provider_name="static",
            model="static-formalizer-model",
        ),
    )
    exact_row = {
        "schema_version": 1,
        "artifact_kind": (
            "RuntimeSourceTheoremExactSemanticDefinitionWorkOrder"
        ),
        "work_order_id": "exact-semantic:survival:baseline-hazard",
        "question_id": question.id,
        "target_theorem_name": "cox_partial_likelihood_consistency",
        "placeholder_symbol": "baselineHazard",
        "candidate_definition_request": {
            "semantic_intent": (
                "Recover the source baseline-hazard definition from theorem "
                "binders and cited local declarations."
            )
        },
        "source_theorem_kernel_verified": False,
        "proof_evidence_status": "WORK_ORDER_NOT_PROOF_EVIDENCE",
    }
    monkeypatch.setattr(
        runtime_module,
        "_formalizer_source_theorem_exact_semantic_definition_work_orders",
        lambda **_kwargs: [dict(exact_row)],
    )
    monkeypatch.setattr(
        runtime_module,
        "_formalizer_theorem_reduction_closure_work_orders",
        lambda **_kwargs: [
            {
                "work_order_id": "closure:must-wait-for-semantic-definition",
                "proof_evidence_status": "WORK_ORDER_NOT_PROOF_EVIDENCE",
            }
        ],
    )
    exact_source_candidate = tmp_path / "exact_source_candidate.lean"
    exact_source_candidate.write_text(
        "theorem cox_partial_likelihood_consistency : True := by trivial\n",
        encoding="utf-8",
    )
    monkeypatch.setattr(
        runtime_module,
        "_runtime_source_theorem_formal_environment_work_order_rows_from_formalizer_targets",
        lambda **_kwargs: [
            {
                "candidate_artifact_path": str(exact_source_candidate),
                "candidate_source_hash": runtime_module.stable_hash(
                    exact_source_candidate.read_text(encoding="utf-8")
                ),
                "target_lean_declaration": (
                    "cox_partial_likelihood_consistency"
                ),
                "target_lean_declaration_source": (
                    "formalizer_structured_source_theorem_target_provenance"
                ),
                "proof_evidence_status": "WORK_ORDER_NOT_PROOF_EVIDENCE",
            }
        ],
    )
    config = ResearchAgentRuntimeConfig(
        theorem_closure_proofengineer_bridge=True,
        source_theorem_formal_environment_proofengineer_bridge=True,
        source_theorem_formal_environment_proofengineer_execute_proof_body=True,
        source_theorem_exact_semantic_definition_source_lookup=True,
        source_theorem_exact_semantic_definition_proofengineer_bridge=True,
        source_theorem_exact_semantic_definition_lean_repair_executor=True,
        source_theorem_exact_semantic_definition_lean_repair_executor_local_lean=False,
    )
    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=formalizer,
        proof_verifier=MockProofVerifier(),
        lean_candidate_root=tmp_path / "candidates",
        runtime_config=config,
    )
    theory_packet = _runtime_sample_response()
    theory_packet_id = str(theory_packet["packet_id"])
    blackboard = BlackboardState(
        project_id="typed-exact-semantic-dispatch",
        artifacts={
            theory_packet_id: theory_packet,
            "simulation_manifest:typed_exact_semantic": {
                "manifest_id": "simulation_manifest:typed_exact_semantic",
                "simulation_passed": True,
            },
            "algorithm_sandbox_manifest:typed_exact_semantic": {
                "manifest_id": "algorithm_sandbox_manifest:typed_exact_semantic",
                "sandbox_passed": True,
            },
        },
    )
    task = AgentTask(
        task_id="formalize:typed_exact_semantic_dispatch",
        owner_subsystem="FormalizationEvaluator",
        objective="Dispatch an exact semantic-definition compiler loop.",
        inputs={
            "question": runtime_module._question_to_payload(question),
            "theory_packet_id": theory_packet_id,
            "simulation_manifest_id": (
                "simulation_manifest:typed_exact_semantic"
            ),
            "algorithm_sandbox_manifest_id": (
                "algorithm_sandbox_manifest:typed_exact_semantic"
            ),
            "architect_context": {},
        },
    )

    result = subsystem.run(task, blackboard)

    assert result.next_task is not None
    assert result.next_task.owner_subsystem == (
        runtime_module.EXACT_SEMANTIC_DEFINITION_SUBSYSTEM
    )
    manifest = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind") == "RuntimeFormalizationManifest"
    )
    assert len(manifest["runtime_exact_semantic_definition_work_orders"]) == 1
    routed_row = manifest["runtime_exact_semantic_definition_work_orders"][0]
    assert routed_row["work_order_id"] == exact_row["work_order_id"]
    assert routed_row["target_theorem_name"] == exact_row["target_theorem_name"]
    assert routed_row["placeholder_symbol"] == exact_row["placeholder_symbol"]
    assert routed_row["question_title"] == question.title
    work_order = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.EXACT_SEMANTIC_DEFINITION_RUNTIME_WORK_ORDER_KIND
    )
    assert work_order["source_formalization_manifest_hash"] == (
        runtime_module.stable_hash(manifest)
    )
    assert work_order["execution_policy"]["proofengineer_bridge_enabled"] is True
    assert work_order["execution_policy"]["lean_repair_executor_enabled"] is True
    assert work_order["execution_policy_fingerprint"] == runtime_module.stable_hash(
        work_order["execution_policy"]
    )
    assert work_order["candidate_artifact_bindings"] == []
    dispatch_evidence = next(
        row
        for row in result.evidence_entries
        if row.evidence_type
        == "exact_semantic_definition_proofengineer_work_order"
    )
    assert dispatch_evidence.status.endswith("NOT_PROOF_EVIDENCE")


def test_theorem_closure_typed_worker_requests_llm_candidate_and_replays_once(
    tmp_path: Path,
) -> None:
    _question, blackboard, dispatch_task, work_order = (
        _theorem_closure_worker_fixture(
            tmp_path,
            lean_source="",
            local_lean=False,
        )
    )
    runner_calls = 0

    def counting_runner(**kwargs: object) -> dict[str, object]:
        nonlocal runner_calls
        runner_calls += 1
        return run_theorem_reduction_closure_proofengineer_bridge(**kwargs)

    worker = runtime_module.TheoremReductionClosureProofEngineerRuntimeSubsystem(
        out_root=tmp_path,
        bridge_runner=counting_runner,
        repair_available=True,
    )

    first = worker.run(dispatch_task, blackboard)

    assert runner_calls == 1
    assert first.status == "REVISE"
    assert first.next_task is not None
    assert first.next_task.owner_subsystem == "ProofEngineer"
    generation_request = next(
        artifact
        for artifact in first.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.THEOREM_REDUCTION_CLOSURE_RUNTIME_GENERATION_REQUEST_KIND
    )
    execution = next(
        artifact
        for artifact in first.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.THEOREM_REDUCTION_CLOSURE_RUNTIME_EXECUTION_KIND
    )
    assert generation_request["runtime_generated_lean"] is False
    assert execution["work_order_id"] == work_order["work_order_id"]
    assert execution["execution_result_status"] == "REVISE"
    assert execution["candidate_bytes_preserved"] is True
    assert execution["runtime_generated_lean"] is False
    blackboard.artifacts.update(first.produced_artifacts)

    replay = worker.run(dispatch_task, blackboard)

    assert runner_calls == 1
    assert replay.status == "REVISE"
    assert replay.next_task == first.next_task
    assert replay.tool_calls == ()
    assert replay.observations[0].observation_type == (
        "theorem_reduction_closure_execution_replayed"
    )
    assert replay.observations[0].payload[
        "bridge_or_compiler_reexecuted"
    ] is False


def test_theorem_closure_typed_worker_accepts_only_exact_kernel_checked_candidate(
    tmp_path: Path,
) -> None:
    exact_source = "theorem closure_candidate : True := by\n  trivial\n"
    _question, blackboard, dispatch_task, _work_order = (
        _theorem_closure_worker_fixture(
            tmp_path,
            lean_source=exact_source,
            local_lean=True,
        )
    )
    trusted_local_lean_evidence = False

    def verified_runner(**kwargs: object) -> dict[str, object]:
        out_dir = Path(kwargs["out_dir"])
        queue_path = Path(kwargs["queue_jsonl"])
        rows = [
            json.loads(line)
            for line in queue_path.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        audit_dir = out_dir / "audit"
        audit_dir.mkdir(parents=True, exist_ok=True)
        candidate_path = audit_dir / "closure_candidate.lean"
        candidate_path.write_text(exact_source, encoding="utf-8")
        row = rows[0]
        check = {
            "work_order_id": row["work_order_id"],
            "target_lean_declaration": row["target_lean_declaration"],
            "kernel_checked_source_excerpt": exact_source[:4000],
            "kernel_checked_source_bytes": len(exact_source.encode("utf-8")),
            "candidate_bytes_preserved": True,
            "lean_export_path": str(candidate_path),
            "status": "KERNEL_VERIFIED",
            "kernel_verified": True,
            "local_lean_attempted": trusted_local_lean_evidence,
            "local_lean_returncode": 0,
            "proof_evidence_status": (
                "KERNEL_VERIFIED_THEOREM_CLOSURE"
            ),
        }
        audit_manifest_path = audit_dir / "manifest.json"
        audit_manifest_path.write_text(
            json.dumps(
                {
                    "artifact_kind": (
                        "TheoremReductionClosureWorkOrderAuditManifest"
                    ),
                    "source_queue_jsonl": str(queue_path.resolve()),
                    "n_work_orders": 1,
                    "n_kernel_verified": 1,
                    "local_lean_requested": True,
                    "all_kernel_verified": True,
                    "proof_evidence_status": (
                        "KERNEL_VERIFIED_THEOREM_CLOSURE_PRESENT"
                    ),
                    "checks": [check],
                }
            ),
            encoding="utf-8",
        )
        learning_path = audit_dir / "learning.jsonl"
        learning_path.write_text("", encoding="utf-8")
        return {
            "artifact_kind": (
                "TheoremReductionClosureProofEngineerBridgeManifest"
            ),
            "source_queue_jsonl": str(queue_path.resolve()),
            "audit_manifest": str(audit_manifest_path),
            "runtime_learning_rows_jsonl": str(learning_path),
            "n_work_orders": 1,
            "n_kernel_verified": 1,
            "runtime_learning_ready": True,
            "local_lean_requested": True,
            "proof_evidence_status": (
                "KERNEL_VERIFIED_THEOREM_CLOSURE_PRESENT"
            ),
        }

    worker = runtime_module.TheoremReductionClosureProofEngineerRuntimeSubsystem(
        out_root=tmp_path,
        bridge_runner=verified_runner,
        repair_available=True,
    )

    rejected = worker.run(dispatch_task, blackboard)

    rejected_execution = next(
        artifact
        for artifact in rejected.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.THEOREM_REDUCTION_CLOSURE_RUNTIME_EXECUTION_KIND
    )
    assert rejected.status == "REROUTE"
    assert rejected.next_task is not None
    assert rejected.next_task.owner_subsystem == "CriticEvaluator"
    assert rejected.failure_classification == (
        "theorem_reduction_closure_execution_contract_invalid"
    )
    assert rejected_execution["all_kernel_verified"] is False
    assert rejected_execution["execution_contract_satisfied"] is False
    assert any(
        "lacks local Lean attempt" in error
        for error in rejected_execution["execution_contract_errors"]
    )

    trusted_local_lean_evidence = True
    result = worker.run(dispatch_task, blackboard)

    execution = next(
        artifact
        for artifact in result.produced_artifacts.values()
        if artifact.get("artifact_kind")
        == runtime_module.THEOREM_REDUCTION_CLOSURE_RUNTIME_EXECUTION_KIND
    )
    assert result.status == "REROUTE"
    assert result.next_task is not None
    assert result.next_task.owner_subsystem == "CriticEvaluator"
    assert execution["all_kernel_verified"] is True
    assert execution["execution_contract_satisfied"] is True
    assert execution["proof_evidence_status"] == (
        "KERNEL_VERIFIED_THEOREM_CLOSURE_PRESENT"
    )
    assert execution["execution_result_status"] == "REROUTE"


def test_theorem_closure_typed_worker_rejects_tampering_before_runner(
    tmp_path: Path,
) -> None:
    _question, blackboard, dispatch_task, work_order = (
        _theorem_closure_worker_fixture(
            tmp_path,
            lean_source="theorem closure_candidate : True := by\n  trivial\n",
            local_lean=False,
        )
    )
    work_order["work_order_rows"][0]["lean_statement_sketch"] = (
        "theorem changed_candidate : True := by\n  trivial\n"
    )
    runner_calls = 0

    def exploding_runner(**_kwargs: object) -> dict[str, object]:
        nonlocal runner_calls
        runner_calls += 1
        raise AssertionError("runner must not be called for a changed work order")

    worker = runtime_module.TheoremReductionClosureProofEngineerRuntimeSubsystem(
        out_root=tmp_path,
        bridge_runner=exploding_runner,
        repair_available=True,
    )

    result = worker.run(dispatch_task, blackboard)

    assert runner_calls == 0
    assert result.status == "BLOCKED"
    assert result.failure_classification == (
        "theorem_reduction_closure_work_order_invalid"
    )
    assert result.tool_calls == ()
    assert result.produced_artifacts == {}


def test_formalization_capability_eval_does_not_replace_live_formalizer_with_deterministic_closure() -> None:
    question = load_open_research_questions(Path("examples/research_questions.json"))[1]
    question_payload = {
        "id": question.id,
        "title": question.title,
        "description": question.description,
        "tags": list(question.tags),
    }
    problem = ProblemFormalizer().formalize(question)
    _procedures, theorem_goals = TheoryPlanner().plan(problem)
    catalog = FormalSubclaimProver().proof_obligation_catalog(problem, theorem_goals)
    verified_ids = [str(row["obligation_id"]) for row in catalog]

    class LiveFormalizerProbe:
        def __init__(self) -> None:
            self.called = False

        def propose(self, **_kwargs: object) -> dict[str, object]:
            self.called = True
            return {
                "schema_version": 1,
                "artifact_kind": "FormalizerProofEngineerProposalPacket",
                "packet_id": "formalizer_proposal:live_probe",
                "source_agent": "LLMFormalizerProofEngineerAgent",
                "provider": "anthropic",
                "backend_provider": "anthropic",
                "model": "claude-sonnet-4-6",
                "model_tier": "sonnet",
                "proof_evidence_status": "LLM_FORMALIZER_PROPOSAL_NOT_PROOF_EVIDENCE",
                "proof_evidence_boundary": "proposal only",
                "kernel_verified": False,
                "full_frontier_theorem_proved": False,
                "formal_targets": [
                    {
                        "id": "split_conformal_live_probe",
                        "informal_source": "live formalizer candidate",
                        "lean_statement_sketch": (
                            "import Mathlib\n"
                            "theorem split_conformal_live_probe : True := by\n"
                            "  trivial\n"
                        ),
                        "semantic_alignment_constraints": [
                            "probe candidate; not source theorem proof"
                        ],
                        "expected_status": "NEEDS_KERNEL_CHECK",
                    }
                ],
                "lemma_dependency_plan": [],
                "retrieval_queries": [
                    {
                        "query": "split conformal coverage",
                        "target_library": "LeanRAG",
                        "purpose": "probe",
                    }
                ],
                "proof_search_plan": {"preferred_tools": ["local_lean"]},
                "proof_bank_obligation_requests": [],
                "gap_taxonomy": [
                    {
                        "gap": "source theorem still unproved",
                        "kind": "source_theorem",
                        "next_owner": "ProofEngineer",
                    }
                ],
                "critic_findings": [
                    {
                        "critic": "probe",
                        "finding": "live formalizer was called",
                    }
                ],
                "next_actions": [
                    {
                        "owner_agent": "ProofEngineer",
                        "action": "kernel-check candidate",
                        "acceptance_gate": "local Lean",
                    }
                ],
            }

    live_formalizer = LiveFormalizerProbe()
    subsystem = FormalizationEvaluatorRuntimeSubsystem(
        proposal_agent=live_formalizer,
        proof_verifier=MockProofVerifier(),
        max_proof_obligations=1,
    )
    blackboard = BlackboardState(
        project_id="test",
        artifacts={
            "theory_packet:test": _runtime_sample_response(),
            "simulation_manifest:test": {"manifest_id": "simulation_manifest:test"},
            "algorithm_sandbox_manifest:test": {
                "manifest_id": "algorithm_sandbox_manifest:test"
            },
        },
    )
    task = AgentTask(
        task_id="task:formalization_capability_eval_live_formalizer",
        owner_subsystem="FormalizationEvaluator",
        objective="do not substitute deterministic closure for live Formalizer in capability eval",
        inputs={
            "question": question_payload,
            "architect_context": {
                "runtime_requested_evidence_contract": {
                    "evaluation_mode": "capability_eval",
                    "capability_eval_requires_formalizer_lean_candidate": True,
                },
                "runtime_learning_memory": {
                    "artifact_kind": "RuntimeLearningMemoryContext",
                    "rows": [
                        {
                            "kernel_verified_proof_obligation_ids": verified_ids,
                            "recommended_proof_obligation_ids": verified_ids,
                        }
                    ],
                },
            },
            "theory_packet_id": "theory_packet:test",
            "simulation_manifest_id": "simulation_manifest:test",
            "algorithm_sandbox_manifest_id": "algorithm_sandbox_manifest:test",
        },
    )

    result = subsystem.run(task, blackboard)
    manifest = next(
        row
        for key, row in result.produced_artifacts.items()
        if key.startswith("formalization_manifest:")
    )
    proposal_id = manifest["llm_formalizer_proof_engineer_proposal_id"]
    proposal = result.produced_artifacts[proposal_id]
    proposal_evidence = next(
        row
        for row in result.evidence_entries
        if row.artifact_id == proposal_id
    )

    assert live_formalizer.called is True
    assert proposal["source_agent"] == "LLMFormalizerProofEngineerAgent"
    assert proposal["provider"] == "anthropic"
    assert proposal["backend_provider"] == "anthropic"
    assert proposal["model"] == "claude-sonnet-4-6"
    assert manifest["formalizer_proposal_source"] == (
        "llm_formalizer_proof_engineer_proposal"
    )
    assert manifest["llm_formalizer_proof_engineer_proposal_observed"] is True
    assert (
        manifest["live_llm_formalizer_proof_engineer_proposal_observed"] is True
    )
    assert (
        manifest["llm_formalizer_proof_engineer_proposal_provider"]
        == "anthropic"
    )
    assert (
        manifest["llm_formalizer_proof_engineer_proposal_backend_provider"]
        == "anthropic"
    )
    assert manifest["deterministic_formalizer_work_order_seed_used"] is False
    assert manifest["formalizer_agentic_capability_evidence_status"] == (
        "LIVE_LLM_FORMALIZER_PROOFENGINEER_PROPOSAL_RECORDED_NOT_PROOF_EVIDENCE"
    )
    assert proposal_evidence.evidence_type == "llm_formalizer_proof_engineer_proposal"
    assert proposal_evidence.evidence_type != (
        "deterministic_theorem_closure_work_order_seed"
    )
    assert manifest["counts"]["theorem_reduction_closure_work_orders"] == 0
    assert manifest["problem_formalization_source"] == (
        "theory_developer_structured_packet"
    )
    assert manifest["legacy_problem_formalizer_used"] is False
    assert manifest["proof_obligation_control"][
        "n_candidate_proof_obligations"
    ] == 0
    assert manifest["proof_obligation_control"][
        "theorem_reduction_closure_required"
    ] is False


