def test_source_theorem_kernel_evidence_registries_separate_raw_and_audit_counts() -> None:
    raw_keys = set(SOURCE_THEOREM_RAW_KERNEL_EVIDENCE_COUNT_KEYS)
    audit_keys = set(SOURCE_THEOREM_AUDIT_KERNEL_EVIDENCE_COUNT_KEYS)
    target_bound_keys = set(SOURCE_THEOREM_TARGET_BOUND_KERNEL_EVIDENCE_COUNT_KEYS)
    target_bound_target_keys = set(
        SOURCE_THEOREM_TARGET_BOUND_KERNEL_EVIDENCE_TARGET_KEYS
    )
    full_frontier_target_bound_keys = set(
        FULL_FRONTIER_TARGET_BOUND_KERNEL_EVIDENCE_COUNT_KEYS
    )
    full_frontier_target_bound_target_keys = set(
        FULL_FRONTIER_TARGET_BOUND_KERNEL_EVIDENCE_TARGET_KEYS
    )
    aggregate_kernel_keys = set(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_KERNEL_EVIDENCE_KEYS
    )
    aggregate_result_keys = set(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_RESULT_ROW_KEYS
    )

    assert audit_keys < raw_keys
    assert aggregate_kernel_keys < raw_keys
    assert len(SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_KERNEL_EVIDENCE_KEYS) == len(
        SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_RESULT_ROW_KEYS
    )
    assert SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_KERNEL_EVIDENCE_KEYS[0] == (
        "source_theorem_formal_environment_proof_body_executor_n_source_theorem_kernel_verified"
    )
    assert SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_RESULT_ROW_KEYS[0] == (
        "source_theorem_formal_environment_proof_body_executor_n_result_rows"
    )
    assert SOURCE_THEOREM_AUDIT_FORMAL_ENV_AGGREGATE_LOCAL_LEAN_CHECK_KEYS[0] == (
        "source_theorem_formal_environment_proof_body_executor_n_local_lean_checked"
    )
    assert all(key.endswith("_n_source_theorem_kernel_verified") for key in aggregate_kernel_keys)
    assert all(key.endswith("_n_result_rows") for key in aggregate_result_keys)
    assert (
        "source_theorem_formal_environment_proof_body_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "external_exact_proof_candidate_rerun_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "external_exact_proof_candidate_rerun_n_source_theorem_kernel_verified"
        in target_bound_keys
    )
    assert (
        "external_exact_proof_candidate_rerun_source_theorem_kernel_verified_target_ids"
        in target_bound_target_keys
    )
    assert (
        "external_exact_proof_candidate_rerun_n_source_theorem_kernel_verified"
        in aggregate_kernel_keys
    )
    assert (
        "external_exact_proof_candidate_rerun_n_result_rows"
        in aggregate_result_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_n_source_theorem_kernel_verified"
        not in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_authoring_retry_materialized_typechecked_review_verifier_approved_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_authoring_retry_materialized_typechecked_review_verifier_approved_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_typechecked_review_verifier_approved_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_materialized_typechecked_review_verifier_approved_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_late_typechecked_review_verifier_approved_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        in raw_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        not in audit_keys
    )
    assert (
        "source_theorem_formal_environment_proof_body_executor_from_source_semantic_promotion_n_source_theorem_kernel_verified"
        in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_proof_body_repair_executor_from_adapter_premise_derivation_feedback_n_source_theorem_kernel_verified"
        in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_typechecked_review_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert (
        "source_theorem_exact_semantic_definition_proof_body_recheck_executor_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert (
        "source_theorem_promotion_post_executor_proofengineer_bridge_n_source_theorem_kernel_verified"
        in audit_keys
    )
    assert (
        "source_theorem_promotion_post_executor_proofengineer_bridge_n_source_theorem_kernel_verified"
        not in aggregate_kernel_keys
    )
    assert "n_source_theorem_target_bound_kernel_verified" in target_bound_keys
    assert "source_theorem_kernel_verified_target_ids" in target_bound_target_keys
    assert (
        "n_full_frontier_target_bound_kernel_verified"
        in full_frontier_target_bound_keys
    )
    assert (
        "full_frontier_theorem_kernel_verified_target_ids"
        in full_frontier_target_bound_target_keys
    )


