def test_runtime_evidence_truth_table_tracks_typechecked_review_recheck_attempt() -> None:
    truth_table = _runtime_evidence_truth_table_from_manifest(
        {
            "n_live_generator_agents_enabled": 6,
            "architect_coordinator_enabled": True,
            "n_algorithm_sandbox_executed": 1,
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_n_result_rows": 1,
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_n_source_theorem_kernel_verified": 0,
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_dominant_failure_classification": (
                "proof_body_incomplete"
            ),
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_first_proof_body_goal_excerpt": [
                "hGoodCovered : ∀ ω, rank ω ∈ GoodRanks -> covered ω",
                "⊢ P {ω | s (Fin.last m) ω ≤ q_hat ω} ≥ ENNReal.ofReal (1 - alpha)",
            ],
            "source_theorem_exact_semantic_definition_late_typechecked_review_proof_body_recheck_executor_n_proof_body_signature_probe_artifact_rows": 1,
            "n_formal_gaps": 1,
        }
    )
    rows = {row["evidence_id"]: row for row in truth_table["rows"]}

    assert truth_table["source_theorem_kernel_verified"] is False
    assert rows["exact_source_proof_body_attempt"]["status"] == (
        "PROOF_BODY_REACHED_OPEN"
    )
    assert rows["exact_source_proof_body_attempt"]["count"] == 1
    assert rows["exact_source_proof_body_attempt"]["proof_evidence"] is False
    assert rows["exact_source_proof_body_attempt"]["blocker"] == (
        "proof_body_incomplete"
    )
    assert any(
        "1 - alpha" in line
        for line in rows["exact_source_proof_body_attempt"]["goal_excerpt"]
    )
    assert rows["full_source_theorem_kernel_evidence"]["status"] == "UNPROVED"
    assert rows["full_source_theorem_kernel_evidence"]["proof_evidence"] is False


