    result_path.write_text("{}", encoding="utf-8")
    manifest = {
        "artifacts": {
            "per_question_results": [
                "runs/live_runtime/conformal_prediction_coverage_runtime_result.json"
            ]
        }
    }

    paths = _resolve_manifest_paths(runtime_dir, manifest)

    assert paths == [result_path]


