    assert rerun["candidate_feedback_rows"][0]["candidate_proof_body"] == (
        long_proof_body
    )
    assert rerun["candidate_feedback_rows"][0]["local_lean_compiled"] is False
    assert rerun["candidate_feedback_rows"][0]["diagnostics"] == [
        "unknown identifier hp"
    ]


